L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "역시 수라장을 넘어 온 숱한 경험이...... 질긴 목숨을 잇게 해 주는군......"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "やはり修羅場をくぐり抜けてきた経験が……\n命を繋いでくれるな……"
L4_1.m_Talk_ENG = "My experience of surviving battlefield after battlefield has saved me once again."
L4_1.m_Talk_TWN = "不愧是通過無數修羅場後累積的豐富經驗…保住了我們一條命..."
L4_1.m_Talk_THA = "ประสบการณ์การเอาชีวิตรอดจากสนามรบนับไม่ถ้วนได้ช่วยฉันเอาไว้อีกครั้งแล้ว"
L4_1.m_Talk_VTN = "Kinh nghiệm sống sót từ chiến trường này đến chiến trường khác đã cứu mình một lần nữa."
L4_1.m_Talk_SCN = "不愧是穿越了无数修罗场后流传下来的经验...能够让我们在危急关头保命..."
L4_1.m_Talk_DEU = "Meine Überlebenserfahrungen auf Schlachtfeldern haben mich ein weiteres Mal gerettet."
L4_1.m_Talk_FRA = "Une fois de plus, mon expérience de survie sur le champ de bataille m'a sauvé la mise."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 1300010
L5_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "시엔 양이 넘었던 수라장은 기껏해야 보충 수업 정도 아니었습니까?"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "シエンさんが経験した修羅場といえば、\nせいぜい補講ぐらいじゃないですか？"
L5_1.m_Talk_ENG = "Battlefields? You mean supplementary lessons."
L5_1.m_Talk_TWN = "小西恩妳通過的修羅場頂多只有留校輔導這種東西而已吧？"
L5_1.m_Talk_THA = "สนามรบ? หมายถึงชั้นเรียนซ่อมเสริมน่ะเหรอ"
L5_1.m_Talk_VTN = "Chiến trường? Ý cậu là những lớp học bổ túc ấy hả."
L5_1.m_Talk_SCN = "西恩小姐你刚刚经历的的战场充其量不过是模拟考而已。"
L5_1.m_Talk_DEU = "Schlachtfelder? Du meinst wohl eher Nachhilfe."
L5_1.m_Talk_FRA = "Le champ de bataille ? Vous voulez parler de vos cours de rattrapage ?"
