L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "うわ～ん♪　結局捕まっちゃったわ～♪"
L6_1.m_Talk_ENG = "Hnnnggg! ♪ In the end, we got caught! ♪"
L6_1.m_Talk_TWN = "嗚嗚嗚♪ 最終還是被抓了~♪"
L6_1.m_Talk_THA = "ฮือออ! ♪ สุดท้ายแล้ว เราก็โดนจับอยู่ดี! ♪"
L6_1.m_Talk_VTN = "Hnnnggg! ♪ Cuối cùng, chúng ta vẫn bị bắt! ♪"
