L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "でもブンブンちゃんにキズが付かなくてよかった♪"
L7_1.m_Talk_ENG = "I'm glad Vroom is safe, though. ♪"
L7_1.m_Talk_TWN = "不過還好我的蓬蓬沒受傷♪"
L7_1.m_Talk_THA = "ดีใจจังที่เจ้าบรึ้นไม่เป็นไร ♪"
L7_1.m_Talk_VTN = "Tôi rất vui vì Vroom vẫn an toàn. ♪"
L7_1.m_Talk_SCN = "不管怎么样，还好蓬蓬没有受伤♪"
L7_1.m_Talk_DEU = "Aber ich bin froh, dass Brumm in Sicherheit ist. ♪"
L7_1.m_Talk_FRA = "Je suis contente que mon Vroum soit en un seul morceau. ♪"
