L10_1 = {}
L10_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 1300010
L10_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_HATE"
L10_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "시끄럽다. 아이리. 이 다음에도 무단결석을 시도할 시엔 붕붕이를 압수하겠다."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "うるさいぞ、アイリ。\n次に無断欠席を図ったらブンブンとやらを押収するからな。"
L10_1.m_Talk_ENG = "Silence! Irie, if you try to play hooky again, I'm seizing your Vroom!"
L10_1.m_Talk_TWN = "吵死了，艾莉。之後妳要是無故缺席，我就要沒收妳的蓬蓬。"
L10_1.m_Talk_THA = "เงียบได้แล้ว ไอรี่! ถ้าเธอพยายามจะโดดเรียนอีก ฉันจะยึดบรึ้นของเธอซะ!"
L10_1.m_Talk_VTN = "Im lặng! Irie, nếu cậu còn chơi trò trốn học một lần nữa, tôi sẽ lấy Vroom của cậu đấy!"
L10_1.m_Talk_SCN = "闭上你的嘴巴，艾力！这之后你如果还企图无故缺席逃跑，我将会没收你的蓬蓬。"
L10_1.m_Talk_DEU = "Ruhe! Irie, wenn du noch einmal versuchst, die Schule zu schwänzen, beschlagnahme ich deinen Brumm!"
L10_1.m_Talk_FRA = "Silence ! Irie, si tu fais encore l'école buissonnière, je confisque ton Vroum !"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 1300010
L11_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L11_1.m_Pos = "R"
L11_1.m_Talk_KOREA = "제지도 무시하고 교정 한복판을 스쿠터로 질주하다니...... 대체 무슨 생각이냐."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "制止を無視して校庭のど真ん中をスクーターで走るなんて……\nいったい何を考えてるんだ？"
L11_1.m_Talk_ENG = "You ignored my warnings and drove your scooter across campus. What were you thinking?"
L11_1.m_Talk_TWN = "竟敢無視勸阻，在校園中騎摩托車……妳到底是怎麼想的？"
L11_1.m_Talk_THA = "เธอไม่ฟังคำเตือนของฉัน และขับสกูตเตอร์ไปทั่วโรงเรียน คิดอะไรของเธออยู่กันแน่?"
L11_1.m_Talk_VTN = "Cậu đã bỏ qua những lời cảnh báo của tôi và lái xe dạo quanh khuôn viên trường. Cậu đã nghĩ gì thế hả?"
L11_1.m_Talk_SCN = "连别人的制止都视若无睹，还敢在校园中用小摩托车疾驰......你到底是怎么想的？"
L11_1.m_Talk_DEU = "Du hast meine Warnungen ignoriert und bist mit deinem Roller über den Campus gerast. Was hast du dir dabei gedacht?"
L11_1.m_Talk_FRA = "Tu as ignoré mes avertissements et conduit en scooter dans le campus. À quoi pensais-tu ?"
