L13_1 = {}
L13_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 1300010
L13_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L13_1.m_Pos = "L"
L13_1.m_Talk_KOREA = "여기서 붕붕이랑 달릴 수 있는 것도 오늘이 마지막인걸......"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "ここでブンブンちゃんを飛ばせるのも今日で最後だもん……"
L13_1.m_Talk_ENG = "Today is the last day I can drive Vroom around this place..."
L13_1.m_Talk_TWN = "因為今天就是能在校園中騎蓬蓬的最後一天嘛……"
L13_1.m_Talk_THA = "วันนี้เป็นวันสุดท้ายที่จะได้ขี่เจ้าบรึ้นนี่ในโรงเรียนแล้ว..."
L13_1.m_Talk_VTN = "Hôm nay là ngày cuối cùng tôi có thể lái Vroom quanh nơi này..."
L13_1.m_Talk_SCN = "能在校园里和我的蓬蓬一起享受飞驰的感觉，今天是最后一次了啊......"
L13_1.m_Talk_DEU = "Heute ist der letzte Tag, an dem ich mit Brumm hier herumfahren kann …"
L13_1.m_Talk_FRA = "C'est la dernière fois qu'Irie peut faire du Vroum ici..."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 1300010
L14_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L14_1.m_Pos = "L"
L14_1.m_Talk_KOREA = "내일부턴 차원 함선 안에 있는 이동 학교로 옮겨야 한다며."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "明日からは次元艦船の中にある移動学校に移るんでしょ？"
L14_1.m_Talk_ENG = "Starting tomorrow, we have to study in the mobile school in the dimensional ship."
L14_1.m_Talk_TWN = "明天我們就得搬到次元艦船中的移動學校去了啊。"
L14_1.m_Talk_THA = "ตั้งแต่พรุ่งนี้เป็นต้นไป เราจะต้องเรียนที่โรงเรียนเคลื่อนที่ในยานข้ามมิติ"
L14_1.m_Talk_VTN = "Bắt đầu từ ngày mai, chúng ta phải học trong trường học di động trên chiến hạm đa chiều rồi."
L14_1.m_Talk_SCN = "从明天开始，我们就要搬到位于次元舰船内的移动学校去了吧？"
L14_1.m_Talk_DEU = "Ab morgen lernen wir in der mobilen Schule auf dem Dimensionsschiff."
L14_1.m_Talk_FRA = "À partir de demain, on étudiera tout en voyageant à bord du vaisseau dimensionnel."
