L16_1 = {}
L16_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 1300010
L16_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L16_1.m_Pos = "L"
L16_1.m_Talk_KOREA = "그냥 그게 너무 아쉬워서...... 그래서 그랬어."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "それがすごく残念で……つい走っちゃったの。"
L16_1.m_Talk_ENG = "I was too sad to leave this place. That's why I did it."
L16_1.m_Talk_TWN = "人家覺得很遺憾....所以才會這麼做..."
L16_1.m_Talk_THA = "ฉันเสียใจมากๆ ที่จะต้องจากที่นี่ไป ก็เลยทำแบบนั้น"
L16_1.m_Talk_VTN = "Tôi quá buồn khi rời khỏi nơi này. Đó là lý do tại sao tôi đã làm thế."
L16_1.m_Talk_SCN = "就是，觉得太遗憾惆怅了....所以之前才这样做的..."
L16_1.m_Talk_DEU = "Ich war traurig, diesen Ort verlassen zu müssen. Deshalb habe ich es getan."
L16_1.m_Talk_FRA = "Irie était super triste de devoir quitter l'école... C'est pour ça qu'elle a fait ça."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@17#Talk"
