L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "그쯤 해 두지, 선도부장."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "そこまでにしとけ、風紀委員長。"
L20_1.m_Talk_ENG = "That's enough, Student Guide Leader."
L20_1.m_Talk_TWN = "就到此為止吧，先鋒部隊長。"
L20_1.m_Talk_THA = "พอได้แล้วน่า หัวหน้าสารวัตรนักเรียน"
L20_1.m_Talk_VTN = "Thế là đủ rồi, Đội Trưởng Đội Sao Đỏ."
L20_1.m_Talk_SCN = "你看，都伤感到这种地步了啊，风纪部部长。"
L20_1.m_Talk_DEU = "Das reicht, Leitende Schülerlotsin."
L20_1.m_Talk_FRA = "Ça suffit, tutrice-en-chef."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 1300010
L21_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L21_1.m_Pos = "C"
L21_1.m_Crash = 20
L21_1.m_Talk_KOREA = "그 이상 소녀를 눈물짓게 한다면! 이 파란을 부르는 전학생, 린 시엔님이 두고 보지 않겠어!"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "それ以上少女を泣かせたら！\nこの波乱を呼び込む転校生、リン・シエン様が黙っていないぞ！"
L21_1.m_Talk_ENG = "If you draw one more tear out of that girl's eyes, I, Lin Xien, the Stormy Transfer Student, will punish you!"
L21_1.m_Talk_TWN = "如果妳再讓這位少女流淚的話，引起這場風波的轉學生—林·西恩是不會坐視不管的！"
L21_1.m_Talk_THA = "ถ้าเธอทำให้แม่หนูนี่เสียน้ำตาอีกหยดเดียว ฉัน หลิน ซีเอิน นักเรียนใหม่ผู้มากับพายุ จะลงโทษเธอเอง!"
L21_1.m_Talk_VTN = "Nếu cậu dám làm cậu ấy rơi thêm một giọt nước mắt nào nữa, thì tôi, Lin Xien, Học Sinh Chuyển Trường Bão Táp, sẽ trừng phạt cậu!"
L21_1.m_Talk_SCN = "如果让这女孩儿流泪的话，引起这出风波的转学生——林·西恩是不会放过你的哦！"
L21_1.m_Talk_DEU = "Wenn du dem Mädchen noch eine Träne aus den Augen lockst, werde ich, die Stürmische Austauschschülerin Lin Xien, dich bestrafen!"
L21_1.m_Talk_FRA = "Si tu arraches une larme de plus aux yeux de cette jeune fille, moi, Lin Xien, la nouvelle Tempête de l'Académie, je te punirai !"
