L23_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE"
L23_1.m_CharStrID = "PILOT_VOICE_NULL_NULL"
L23_1.m_Talk_KOREA = "<color=#ffd34c>아가씨. 저희는 이만 격납고가 있는 제 12 별장으로 복귀하겠습니다.</color>"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "<color=#ffd34c>お嬢様。私たちは格納庫がある第12別荘に帰還いたします。</color>"
L23_1.m_Talk_ENG = "<color=#ffd34c>My Lady, let us return to the hangar at your twelfth villa now.</color>"
L23_1.m_Talk_TWN = "<color=#ffd34c>小姐，我們回到設有機庫的第12別墅吧。</color>"
L23_1.m_Talk_THA = "<color=#ffd34c>คุณหนูครับ เราจะกลับไปที่โรงจอดยานของคฤหาสน์หลังที่ 12 แล้วนะครับ</color>"
L23_1.m_Talk_VTN = "<color=#ffd34c>Thưa Tiểu Thư, xin hãy cho phép chúng tôi quay về Xưởng bảo lưu tại biệt thự thứ mười hai.</color>"
L23_1.m_Talk_SCN = "<color=#ffd34c>小姐，要是没什么事了的话，请允许我们回到您名下第12别墅的地下机库。</color>"
L23_1.m_Talk_DEU = "<color=#ffd34c>Mylady, lass uns zum Hangar deiner zwölften Villa zurückkehren.</color>"
L23_1.m_Talk_FRA = "<color=#ffd34c>Madame, nous devons retourner au hangar de votre douzième villa.</color>"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "SPRING_ACT1_EPILOUGE@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 1300010
L24_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_LAUGH"
L24_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "아, 그래. 응원해 주느라 고생 많았어. 퇴근해도 좋아."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "ああ、わかった。応援ご苦労だった。もう帰っていいぞ。"
L24_1.m_Talk_ENG = "Ah, okay. Thank you for your support. You may go home now."
L24_1.m_Talk_TWN = "啊，好的。為我加油的各位辛苦了，大家可以回去囉。"
L24_1.m_Talk_THA = "อ๊ะ ได้สิ ขอบคุณที่ช่วยพวกเรานะ กลับบ้านไปเถอะ"
L24_1.m_Talk_VTN = "À, được rồi. Cảm ơn sự hỗ trợ của anh nhé. Anh có thể về nhà rồi."
L24_1.m_Talk_SCN = "啊，好啊。为了支持我，大家都辛苦了啊，现在就下班也蛮好的。"
L24_1.m_Talk_DEU = "Ah, okay. Danke für die Unterstützung. Du darfst jetzt nach Hause gehen."
L24_1.m_Talk_FRA = "Oh, d'accord. Merci de votre aide, vous pouvez rentrer."
