L27_1 = {}
L28_1 = "SPRING_ACT1_EPILOUGE@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 1300010
L27_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L27_1.m_Pos = "R"
L28_1 = "......시엔, 입학식 때부터 본 사이에 갑자기 무슨 전학생 소리지?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "……シエン、君のことは入学式から見ているのだが転校生とはどういうことだ？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Xien, why do you call yourself a transfer student? You've been here since your entrance ceremony."
L27_1.m_Talk_ENG = L28_1
L28_1 = "…西恩，從入學典禮當天起就說自己是轉學生，這到底算什麼的轉學生啊?"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ซีเอิน ทำไมเธอเรียกตัวเองว่านักเรียนใหม่น่ะ? เธอก็เข้าเรียนที่นี่ตั้งแต่พิธีปฐมนิเทศไม่ใช่เรอะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Xien, tại sao cậu lại tự xưng là học sinh chuyển trường vậy? Cậu đã ở đây từ lúc khai giảng mà."
L27_1.m_Talk_VTN = L28_1
L28_1 = "......西恩同学，你从入学典礼开始就在这所学校了，转学生这个称呼并不妥当。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Xien, warum bezeichnest du dich ständig als Austauschschülerin? Du bist doch schon seit der Aufnahmezeremonie hier."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Xien, pourquoi te qualifies-tu d'élève transférée ? Tu es présente depuis la cérémonie de rentrée."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "SPRING_ACT1_EPILOUGE@28#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 28
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 1300010
L28_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L28_1.m_Pos = "L"
L29_1 = "그냥 재학생은 심심하잖아. 전학생이 아니면 폼이 안 난다구."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ただの在学生じゃあつまらない。転校生とでも言わないとカッコがつかないだろ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Just being a student is boring. Being a transfer student, however, sounds exciting."
L28_1.m_Talk_ENG = L29_1
L29_1 = "只是一般學生不是很無聊嗎？只有轉學生才能引起風波啊。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ก็เป็นนักเรียนธรรมดามันน่าเบื่อนี่ เป็นนักเรียนใหม่มันน่าตื่นเต้นกว่าตั้งเยอะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Chỉ là học sinh thôi thì chán lắm. Làm một học sinh chuyển trường thì nghe có vẻ thú vị hơn nhiều."
L28_1.m_Talk_VTN = L29_1
L29_1 = "切，普通学生的话多没意思，就是要当转校生才帅气嘛。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Schülerin zu sein ist auf Dauer langweilig. Ein Studienortwechsel klingt aufregend!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Être une élève ordinaire, c'est ennuyeux à mourir. Être une élève transférée, en revanche, c'est exaltant !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SPRING_ACT1_EPILOUGE@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 1300010
L29_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_LAUGH"
L29_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L30_1 = "R_M_I"
L29_1.m_Pos = L30_1
L30_1 = "오오~ 그럼 아이리 님도 오늘부터 파랑의 전학생 할래♪"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "おお～じゃあ、アイリ様も今日からパランの転校生になる♪"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Oooh, then Irie wants to be a Stony Transfer Student, too! ♪"
L29_1.m_Talk_ENG = L30_1
L30_1 = "喔喔~那從現在開始艾莉也要當引起奔波的轉學生~♪"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อู้วว ไอรี่ก็อยากเป็นนักเรียนใหม่ผู้มากับอายุบ้างจังเลย! ♪"
L29_1.m_Talk_THA = L30_1
L30_1 = "Ồ, thì Irie cũng muốn trở thành Học Sinh Chuyển Trường Bất Hợp Pháp! ♪"
L29_1.m_Talk_VTN = L30_1
L30_1 = "哦哦~那从现在开始艾力也要当奔波不断的转校生~♪"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Oooh, dann will Irie auch Türmende Austauschschülerin sein! ♪"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oooh, Irie veut aussi être une Choupette transférée ! ♪"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
