L31_1 = 40
L30_1.m_Crash = L31_1
L31_1 = "파랑이 아니라 파란이야!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "パランじゃなくて波乱だ！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Not Stony—it's Stormy!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "不是奔波，是風波！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไม่ใช่อายุ—พายุย่ะ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Không phải Bất Hợp Pháp – là Bão Táp!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "不是奔波，是风波啊！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Nicht türmende – stürmische!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "C'est Tempête, pas Choupette !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "SPRING_ACT1_EPILOUGE@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 1300010
L31_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_PRIDE"
L31_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L31_1.m_Pos = "L"
L32_1 = "그리고 전학생은 한 명으로 충분하다구."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "それに、転校生は私一人で十分だ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Besides, this school doesn't need two transfer students."
L31_1.m_Talk_ENG = L32_1
L32_1 = "還有，轉學生只要有一個就夠了！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แล้วก็ โรงเรียนนี้น่ะ ไม่ต้องการนักเรียนใหม่สองคนหรอกนะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hơn nữa, ngôi trường này không cần hai học sinh chuyển trường đâu."
L31_1.m_Talk_VTN = L32_1
L32_1 = "还有，转校生只要有一个就够了啊！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Außerdem braucht diese Schule keine zwei Austauschschülerinnen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Et cette école n'a pas besoin de deux élèves transférées."
L31_1.m_Talk_FRA = L32_1
