L33_1 = "에이~ 그러지 말구 아이리 님도 전학생 시켜 주라~♪"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ええ～そう言わずにアイリ様にも転校生やらせてよ～♪"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Come on, let Irie be a transfer student, too! ♪"
L32_1.m_Talk_ENG = L33_1
L33_1 = "哎呀~別這樣嘛~讓艾莉也當轉學生嘛~♪"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อย่าพูดแบบนั้นเลยน่า ให้ไอรี่เป็นนักเรียนใหม่ด้วยเถอะนะ! ♪"
L32_1.m_Talk_THA = L33_1
L33_1 = "Thôi nào, cho Irie làm học sinh chuyển trường với! ♪"
L32_1.m_Talk_VTN = L33_1
L33_1 = "哎呀~别这样嘛~让本艾力大人也转学吧~♪"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Komm schon, lass Irie auch Austauschschülerin sein! ♪"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Allez, laisse Irie être une élève transférée aussi !"
L32_1.m_Talk_FRA = L33_1
