L36_1 = "푸른 하늘과 청춘은 서로를 끌어당기는 자석과도 같은 것."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "青空と青春は互いに引き寄せあう磁石のようなもの。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "The blue sky and youth pull each other like magnets."
L35_1.m_Talk_ENG = L36_1
L36_1 = "藍色的天和青春就像磁鐵一樣，兩個東西是互相吸引的。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ท้องฟ้าสีครามกับวัยรุ่นน่ะ มีแรงดึงดูดต่อกันเหมือนกับแม่เหล็ก"
L35_1.m_Talk_THA = L36_1
L36_1 = "Trời xanh và tuổi trẻ tự động hút về phía nhau như hai thỏi nam châm."
L35_1.m_Talk_VTN = L36_1
L36_1 = "蓝色的、波澜壮阔的天空和青春啊，就像是磁铁一般，相互吸引着、充满魅力无比契合。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Der blaue Himmel und die Jugend ziehen sich gegenseitig an wie Magnete."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Le bleu du ciel et la jeunesse s'attirent comme des aimants."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "SPRING_ACT1_EPILOUGE@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 1300010
L36_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L36_1.m_Pos = "C"
L37_1 = "그런 자연스러운 섭리를 교칙으로 통제하려 하다니! 그야말로 반자연, 반인륜적인 억압 아닌가!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そのような自然の摂理を校則で縛ろうとするなんて！\nそれこそ反自然、反倫理的な抑圧ではないか！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You can't control such a natural phenomenon in the name of school rules. That's unnatural and unethical suppression!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "但人們竟然想用校規來控制這種自然的反則！這不正是反自然，反人性的壓迫嗎!"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เธอจะใช้กฎของโรงเรียนควบคุมปรากฏการณ์ธรรมชาติแบบนั้นไม่ได้หรอกนะ มันเป็นการฝ่าฝืนธรรมชาติ และเป็นการกีดกันที่ไร้คุณธรรม!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cậu không thể kiểm soát một hiện tượng tự nhiên như vậy nhân danh các quy tắc của trường được. Đó là một sự đàn áp phi tự nhiên và phi đạo đức!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "所以怎么能用校规来控制这种想要奔跑的自然规律呢！这不是反自然,反人类的压迫吗!"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Man kann solche Naturgewalten nicht mit Schulregeln kontrollieren. Das wäre unnatürliche und unmoralische Unterdrückung!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "On ne peut pas contrôler un tel phénomène au nom d'un règlement. C'est contre nature ! C'est une répression immorale !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
