L39_1 = "오, 그런 거였어? 그렇다면 아이리가 뛰쳐나간 것도 납득이 가는 걸?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "おお、そういうことなのか？　そう言われたらアイリが飛び出したのも納得だな。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Oh, really? That explains why Irie ran out of the school."
L38_1.m_Talk_ENG = L39_1
L39_1 = "哦，是這樣嗎？那艾莉跑出去也是情有可原的囉？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โอ้ งั้นเรอะ? ถึงว่า ทำไมไอรี่ถึงโดดเรียน"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ồ, vậy à? Điều đó giải thích tại sao Irie lại chạy khỏi trường đấy."
L38_1.m_Talk_VTN = L39_1
L39_1 = "哦，是这样吗？那艾力飞跑出去也是情有可原的咯？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ach, so ist das … Das erklärt, warum Irie aus der Schule geflohen ist."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ah oui ? Ça explique pourquoi Irie a quitté l'école."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
