L46_1 = "그래. 솔선수범해야 할 나 역시 과실을 저질렀으니, 이번 건에 대해선 보류하겠다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "わかった。模範を見せるべき私も過ちを犯したのだから、今回の件は保留にしよう。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Okay, since this is also partly my mistake, I'll let it slide."
L45_1.m_Talk_ENG = L46_1
L46_1 = "好吧，本應以身作則的我也犯了錯，那對這次的事情我就不追究了。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เอาเถอะ ในเมื่อเรื่องนี้ฉันก็มีส่วนผิดด้วย เพราะฉะนั้นคราวนี้ฉันจะไม่เอาเรื่องอะไร"
L45_1.m_Talk_THA = L46_1
L46_1 = "Được rồi, vì đây cũng có một phần sai lầm của tôi, tôi sẽ bỏ qua chuyện này."
L45_1.m_Talk_VTN = L46_1
L46_1 = "好吧，本应以身作则的我也犯了错误，对这次事件呢，我就持保留意见。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Okay, da die Angelegenheit teilweise mein Fehler ist, lasse ich es durchgehen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Très bien, comme je suis partiellement en faute, je ferme les yeux pour cette fois."
L45_1.m_Talk_FRA = L46_1
