L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 1300010
L48_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_LAUGH"
L48_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L48_1.m_Pos = "C"
L48_1.m_Crash = 30
L49_1 = "고마워! 정말 고마워, 선도부장!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ありがとう！　本当にありがとう、風紀委員長！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Thank you! Thank you so much, Student Guide Leader!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "謝謝！真的太感謝你了，先鋒部隊長！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ขอบคุณนะคะ! ขอบคุณมากๆ เลย หัวหน้าสารวัตรนักเรียน!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Cảm ơn cậu! Cảm ơn cậu rất nhiều, Đội Trưởng Đội Sao Đỏ!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "谢谢！真的太感谢你了，风纪部部长！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Danke! Vielen Dank, Leitende Schülerlotsin!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Merci ! Merci beaucoup, Esther !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
