L51_1 = "SPRING_ACT1_EPILOUGE@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 1300010
L50_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_LAUGH"
L51_1 = "SEO_YOON_ALT_SPRING_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "L"
L51_1 = "이야...... 그 깐깐한 선도부장이 사정을 봐 주는 날도 오고, 의외네."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "わぁ……あの厳しい風紀委員長が\n人の事情を聞いてくれる日がくるなんて意外ね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Wow! Who knew the fastidious Student Guide Leader would make an exception for someone one day?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "竟然…鐵血的先鋒部隊長也有關照我的這一天，我太意外了。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ว้าว! ใครจะไปรู้ว่าหัวหน้าสารวัตรนักเรียนผู้เข้มงวดก็ยกโทษให้ใครสักคนเป็นด้วย?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Wow! Ai mà ngờ rằng một ngày nào đó, Đội Trưởng Đội Sao Đỏ khó tính sẽ tạo ra một ngoại lệ cho người khác cơ chứ?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "哎呀...性格古板脾气又犟的风纪部部长，也有关照人的一天，真让人意外。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wer hätte gedacht, dass die pedantische Leitende Schülerlotsin eines Tages mal eine Ausnahme für jemanden machen würde?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Waouh ! Qui aurait cru que l'implacable tutrice-en-chef ferait un jour une exception ?"
L50_1.m_Talk_FRA = L51_1
