L2_1 = "SPRING_ACT1_EPILOUGE@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 1300010
L1_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_PRIDE"
L1_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L2_1 = "R_M_I"
L1_1.m_Pos = L2_1
L2_1 = "외강내유라 했던가."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "外剛内柔という言葉があるだろう。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "A soft heart under a stern exterior, as they say."
L1_1.m_Talk_ENG = L2_1
L2_1 = "真是刀子嘴豆腐心。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "หัวใจที่อ่อนโยน ภายใต้ฉากหน้าที่แข็งกร้าวสินะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ngoài rắn trong mềm, như người ta thường nói đó."
L1_1.m_Talk_VTN = L2_1
L2_1 = "真是刀子嘴豆腐心啊。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Harte Schale, weicher Kern, wie man sagt."
L1_1.m_Talk_DEU = L2_1
L2_1 = "C'est un cœur tendre dissimulé derrière un masque d'austérité."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "SPRING_ACT1_EPILOUGE@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 1300010
L2_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L2_1.m_Pos = "R"
L3_1 = "본래 저렇게 철벽 같은 인물일수록 내면은 솜사탕처럼 부드러운 법이지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ああやって強そうに見える人物ほど、内面は綿あめのように柔らかいものだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "People who seem inaccessible like her often have a heart of gold."
L2_1.m_Talk_ENG = L3_1
L3_1 = "果然，外表越是像鐵壁一樣的人物，內心就越是像棉花糖柔軟啊。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คนที่เปิดใจยากอย่างเธอมักจะมีหัวใจที่งดงามดุจทองคำ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Những người trông có vẻ khó tiếp cận như cậu ấy thường có một trái tim vàng."
L2_1.m_Talk_VTN = L3_1
L3_1 = "原来外表越是像铁壁一样的人物,内心越是像棉花糖一样柔软啊。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Menschen, die so unnahbar erscheinen wie sie, haben oft ein Herz aus Gold."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Les personnes qui paraissent inaccessibles, comme elle, ont souvent un cœur d'or."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "SPRING_ACT1_EPILOUGE@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 1300010
L3_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L3_1.m_Pos = "R"
L4_1 = "훗훗. 그나저나 또 전학생답게 잠잠하던 수면에 파문을 일으키고 말았나......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ふふっ。また転校生らしく静かな水面に波紋を起こしてしまったか……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Hah hah. By the way, I caused a ripple in the calm lake again, like the great transfer student I am."
L3_1.m_Talk_ENG = L4_1
L4_1 = "呵呵，難道又要像轉學生一樣，在平靜的水面上引起一陣波紋嗎…？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฮ่าฮ่า และฉัน ก็ทำให้เกิดระลอกคลื่นในทะเลสาบที่เงียบสงบอีกครั้ง สมแล้วกับฉายานักเรียนใหม่ผู้ยิ่งใหญ่"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ha ha. Nhân tiện, tôi lại gây ra một gợn sóng trong mặt hồ phẳng lặng, như một học sinh chuyển trường tuyệt vời."
L3_1.m_Talk_VTN = L4_1
L4_1 = "哼哼，不愧是一生波澜壮阔的转校生呢，校园这摊平静的湖水，今天又因为我林·西恩而起了涟漪呢...？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Haha … Übrigens habe ich mal wieder ein paar Wellen geschlagen – als großartige Austauschschülerin, die ich bin."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ha ha ha, la grande élève transférée que je suis a encore provoqué des vaguelettes dans le calme du lac."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
