L6_1 = "SPRING_ACT1_EPILOUGE@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 1300010
L5_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L5_1.m_Pos = "C"
L6_1 = "방금 전에는 파란 아니었습니까?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "さっきは波乱だと言いませんでしたか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Aren't you the stormy transfer student anymore?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "剛才不就已經是一場風波了嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เธอไม่เป็นนักเรียนใหม่ผู้มากับพายุแล้วเหรอ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Cậu không còn là học sinh chuyển trường bão táp nữa sao?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "嗯？刚才不还是“风波不断”的转校生吗？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Bist du nicht mehr die stürmische Austauschschülerin?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Vous n'êtes plus la nouvelle Tempête de l'Académie ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "SPRING_ACT1_EPILOUGE@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 1300010
L6_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_HATE"
L6_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L6_1.m_Pos = "C"
L6_1.m_Crash = 30
L7_1 = "그, 그게 그거 아니겠냐구."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ど、どっちもどっちだろう。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "S-same difference."
L6_1.m_Talk_ENG = L7_1
L7_1 = "那、那不算吧？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "กะ-ก็คล้ายๆ กันล่ะน่า"
L6_1.m_Talk_THA = L7_1
L7_1 = "G-giống nhau cả thôi"
L6_1.m_Talk_VTN = L7_1
L7_1 = "那、那不算吧？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "… Geht nicht beides?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "C-C'est pareil."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SPRING_ACT1_EPILOUGE@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 1300010
L7_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L7_1.m_Pos = "C"
L8_1 = "아카데미의 학생이라면 일관성을 지켜 주십시오."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "アカデミーの生徒なら、一貫性を保ってください。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "We students of the Academy must be consistent with all our endeavors."
L7_1.m_Talk_ENG = L8_1
L8_1 = "作為本校的學生，請妳說話算話。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "พวกเรานักเรียนแห่งวิทยาลัย จะต้องยึดมั่นในความตั้งใจของเราไม่เปลี่ยนแปลงสิ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Chúng ta, những học sinh của Học Viện phải nhất quán với tất cả những nỗ lực của chúng ta."
L7_1.m_Talk_VTN = L8_1
L8_1 = "作为本校的学生，我们就要统一口径。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wir Schüler der Akademie sollten bei allen unseren Unternehmungen konsequent sein."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Nous, élèves de l'Académie, nous devons d'être cohérents dans toutes nos entreprises."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
