L11_1 = "SPRING_ACT1_EPILOUGE@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 1300010
L10_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_LAUGH"
L11_1 = "YOO_JIN_ALT_SPRING_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "R_M_I"
L10_1.m_Pos = L11_1
L11_1 = "서기는 참 한결 같네. 학생회장이 믿는 이유가 있다니까."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "書記はほんと変わらないな。生徒会長が信頼するだけある。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Clerk, you're always the same. There's a reason the Student President trusts you so much."
L10_1.m_Talk_ENG = L11_1
L11_1 = "書記就說一是一，說二是二…怪不得學生會長這麼相信你！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เสนาธิการ คุณนี่ไม่เคยเปลี่ยนเลยนะ นี่คงเป็นเหตุผลที่ประธานนักเรียนเชื่อใจคุณขนาดนี้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Thư Ký, lúc nào cậu cũng thế cả. Chủ Tịch Hội Học Sinh tin tưởng cậu nhiều như vậy là có lý do đấy nhỉ."
L10_1.m_Talk_VTN = L11_1
L11_1 = "书记真是一如既往的较真啊...难怪学生会长这么信任你！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Sachbearbeiter, du bist immer derselbe. Das ist wohl der Grund, warum die Schülerpräsidentin dir so viel Vertrauen schenkt."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Vous ne changez pas, monsieur le secrétaire. C'est pour ça que la présidente du Conseil vous fait confiance."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SPRING_ACT1_EPILOUGE@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 1300010
L11_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L11_1.m_Pos = "L"
L12_1 = "학생회장님이 믿는 건 학우 전원입니다. 오해를 살 만한 발언은 삼가 주십시오."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "生徒会長が信頼しているのは学友の皆さんです。\n誤解を招くような発言はやめてください。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "The Student President trusts everyone in school. Please avoid such misleading comments."
L11_1.m_Talk_ENG = L12_1
L12_1 = "學生會長是相信我們所有學生。請妳不要發表會引起誤會的言論。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ประธานนักเรียนเชื่อใจทุกคนในโรงเรียนนี้ โปรดอย่าแสดงความคิดเห็นที่ทำให้เกิดความเข้าใจผิดแบบนั้น"
L11_1.m_Talk_THA = L12_1
L12_1 = "Chủ Tịch Hội Học Sinh tin tưởng tất cả mọi người trong trường. Hãy tránh những bình luận gây hiểu lầm như vậy."
L11_1.m_Talk_VTN = L12_1
L12_1 = "不，学生会长相信着我们全体学员。请不要发表容易引起误会的言论。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Die Schülerpräsidentin vertraut jedem in der Schule. Bitte vermeide solch irreführende Kommentare."
L11_1.m_Talk_DEU = L12_1
L12_1 = "La présidente du Conseil fait confiance à tous les membres de cette Académie. Je vous prie d'éviter ce genre de commentaires trompeurs."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SPRING_ACT1_EPILOUGE@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 1300010
L12_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L12_1.m_Pos = "L"
L13_1 = "아니면 혹시 본인만 학생회장님의 신뢰를 독차지하고 싶은 겁니까?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "それとも、ひょっとして生徒会長の信頼を独り占めしたいのですか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Or did you say that because you want to keep her trust to yourself?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "還是說你想一個人獨佔學生會長的信任?"
L12_1.m_Talk_TWN = L13_1
L13_1 = "หรือที่คุณพูดแบบนั้น เพราะอยากจะเก็บความเชื่อใจของเธอไว้กับตัวเองคนเดียวกัน?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Hay cậu nói vậy vì cậu muốn giữ lòng tin của cậu ấy cho riêng mình?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "还是说你一人想独占学生会长的信任?"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Oder sagst du das nur, weil du ihr Vertrauen für dich behalten willst?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Peut-être que vous avez dit ça parce que vous aimeriez garder sa confiance pour vous..."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SPRING_ACT1_EPILOUGE@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 1300010
L13_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_HATE"
L14_1 = "YOO_JIN_ALT_SPRING_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L13_1.m_Crash = 20
L14_1 = "윽...... 뭐든 쓸데없이 진지하긴......"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "うっ……ほんと無駄に真剣だな……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Gosh, do you always have to be so serious?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "唔…你真是，什麼都這麼計較..."
L13_1.m_Talk_TWN = L14_1
L14_1 = "โอ๊ย นี่นายจะต้องซีเรียสแบบนี้ตลอดเวลาเลยหรือไง?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Thánh thần ơi, lúc nào cậu cũng phải nghiêm túc như vậy sao?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "额...你真是，对什么都是这样较真..."
L13_1.m_Talk_SCN = L14_1
L14_1 = "Musst du denn immer so verbissen sein?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Pourquoi vous prenez toujours tout au sérieux ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "SPRING_ACT1_EPILOUGE@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 1300010
L14_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L14_1.m_Pos = "L"
L15_1 = "무려 유진 양과의 잡담에 성의껏 임한다고 해 주십시오."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "シロコさんとの雑談に誠意をもって付き合ってるんですよ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I'm only trying to chat with you to the best of my ability."
L14_1.m_Talk_ENG = L15_1
L15_1 = "誰來告訴我要怎麼和小劉珍說話。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ผมแค่พยายามจะพูดคุยเล่นกับคุณอย่างสุดความสามารถก็เท่านั้นเอง"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi chỉ cố gắng trò chuyện với cậu trong khả năng có thể của mình thôi."
L14_1.m_Talk_VTN = L15_1
L15_1 = "我只是在尽力接上与刘珍小姐的对话。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich versuche nur, mich nach bestem Wissen und Gewissen mit dir zu unterhalten."
L14_1.m_Talk_DEU = L15_1
L15_1 = "J'essaie simplement de faire la conversation."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SPRING_ACT1_EPILOUGE@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 1300010
L15_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L15_1.m_Pos = "L"
L16_1 = "의미도 맥락도 없는 잡담으로 시간을 허비하는 것보다는 훨씬 건설적이겠죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "意味も脈絡もない雑談で時間を無駄にするよりは、ずっと建設的でしょうから。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I bet talking to me is much more constructive than chatting meaninglessly with others."
L15_1.m_Talk_ENG = L16_1
L16_1 = "比起在沒有意義和邏輯的閒談上浪費時間，我說的話更有建設性吧。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ผมมั่นใจว่าการได้พูดคุยกับผมนั้น ยังไงก็เป็นสิ่งที่สร้างสรรค์กว่าการคุยเล่นไร้สาระกับคนอื่น"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi cá rằng nói chuyện với tôi mang tính xây dựng hơn nhiều so với những cuộc trò chuyện vô nghĩa với những người khác."
L15_1.m_Talk_VTN = L16_1
L16_1 = "相信我，这比你和其他人毫无意义、也没有逻辑的闲谈相比，更有价值。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ein Gespräch mit mir ist doch sicher weit konstruktiver als irgendein sinnloses Geplauder mit anderen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Eh bien, je parie que c'est plus constructif pour vous de parler avec moi que d'avoir une conversation insensée avec les autres."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "SPRING_ACT1_EPILOUGE@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 1300010
L16_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "YOO_JIN_ALT_SPRING_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "R"
L16_1.m_Crash = 30
L17_1 = "......넌 진짜 입만 열었다 하면 왕재수야."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "……お前はほんと、口を開けば人をムカつかせるな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Every time you open your mouth, you make me want to hurt you."
L16_1.m_Talk_ENG = L17_1
L17_1 = "……你真的是只要開口就讓人覺得你很可惡耶。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ทุกครั้งที่นายเปิดปากทีไร มันก็ทำให้ฉันอยากจะซัดหน้านายทุกครั้ง"
L16_1.m_Talk_THA = L17_1
L17_1 = "Mỗi lần cậu mở miệng, cậu đều khiến tôi muốn đấm cậu đấy."
L16_1.m_Talk_VTN = L17_1
L17_1 = ".....额，你真是开口就让人觉得没劲了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Immer, wenn du den Mund aufmachst, endet es darin, dass ich dir wehtun möchte …"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Chaque fois que vous ouvrez la bouche, j'ai envie de vous taper."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SPRING_ACT1_EPILOUGE@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 1300010
L17_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L17_1.m_Pos = "L"
L18_1 = "이렇게까지 쉽게 설명해 드리는데 이해를 못하시면 저도 다른 방법이 없습니다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ここまでわかりやすく説明しているのに\n理解できないとおっしゃるなら、僕には他に方法がありません。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I've tried to make things as easy as possible for you. If you still don't understand them, then I can't help you."
L17_1.m_Talk_ENG = L18_1
L18_1 = "我已經解釋得已經這麼清楚了，如果妳還是無法理解的話，我也沒有辦法。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ผมพยายามพูดให้เรื่องทุกอย่างมันเข้าใจง่ายสำหรับคุณแล้ว ถ้าคุณยังไม่เข้าใจอีก ผมก็คงจะช่วยไม่ได้"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi đã cố gắng giúp nó dễ hiểu nhất có thể với cậu rồi. Nếu cậu vẫn không hiểu, thì tôi cũng đành bất lực thôi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "我解释得已经这么简单明白了，如果你还是理解不了的话,我也别无他法了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich habe versucht, dir die Dinge möglichst einfach darzustellen. Wenn du sie trotzdem nicht verstehst, kann ich dir auch nicht helfen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Pourtant, j'essaie de m'exprimer en termes simples. Si vous ne comprenez toujours pas, je ne peux rien pour vous."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "SPRING_ACT1_EPILOUGE@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 1300010
L18_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L18_1.m_Pos = "L"
L19_1 = "유진 양의 학습 능력은 역시 재검증이 필요하겠군요. 더 치밀한 커리큘럼을 준비하겠습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "やはりシロコさんの学習能力は再検証する必要がありそうです。\nさらに緻密なカリキュラムを用意します。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Eujin, clearly your learning ability needs reevaluation. I'll come up with a more meticulous curriculum for you."
L18_1.m_Talk_ENG = L19_1
L19_1 = "小劉珍的學習能力果然需要重新檢驗。我會幫妳準備更縝密的課程。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ยูจิน คุณต้องเข้ารับการประเมินทักษะการเรียนรู้ใหม่แล้วล่ะ ผมจะพยายามหาหลักสูตรที่ละเอียดกว่านี้ให้นะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Eujin, rõ ràng khả năng học tập của cậu cần được đánh giá lại. Tôi sẽ đưa ra một chương trình giảng dạy tỉ mỉ hơn cho cậu."
L18_1.m_Talk_VTN = L19_1
L19_1 = "刘珍你的学习能力还是需要检验或者提高一下啊，最好准备选修一些更周密的课程。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Eujin, deine Lernfähigkeit muss offensichtlich auf den Prüfstand gestellt werden. Ich werde einen ausgefeilteren Lehrplan für dich ausarbeiten."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Eujin, je crois que votre capacité d'apprentissage doit être réévaluée. Je vous mettrai au point un programme plus rigoureux."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "SPRING_ACT1_EPILOUGE@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 1300010
L19_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS"
L20_1 = "YOO_JIN_ALT_SPRING_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = 40
L19_1.m_Crash = L20_1
L20_1 = "아, 안 돼. 넌 보충 수업이랍시고 숙제는 대학교처럼 내 주잖아."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "や、やめろ。お前は補講と言って大学並みの宿題を出すじゃないか。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "N-no! Even university students can't do the homework you come up with."
L19_1.m_Talk_ENG = L20_1
L20_1 = "喔不，像補習班、大學作業那樣嗎？千萬不要。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "มะ-ไม่นะ! ขนาดนักเรียนมหาวิทยาลัยยังทำการบ้านที่นายคิดไม่ได้เลย"
L19_1.m_Talk_THA = L20_1
L20_1 = "K-không! Ngay cả sinh viên đại học cũng không thể làm được bài tập của cậu đâu."
L19_1.m_Talk_VTN = L20_1
L20_1 = "啊别了吧，像补习班、课外作业一样吗？不了不了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "N-nein! Selbst Universitätsstudenten können die Hausaufgaben, die deinem Hirn entspringen, nicht bewältigen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "N-Non ! Vos devoirs sont trop difficiles, même pour les étudiants de l'université !"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "SPRING_ACT1_EPILOUGE@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 1300010
L20_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_PRIDE"
L21_1 = "YOO_JIN_ALT_SPRING_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L20_1.m_Crash = 30
L21_1 = "그렇지, 야옹아! 네가 있었지!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そうだ、にゃんこちゃん！　お前がいたな！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Oh right, kitty cat, I totally forgot I had you!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒錯…貓貓！你在這裡啊!"
L20_1.m_Talk_TWN = L21_1
L21_1 = "โอ๊ะ เจ้าเหมียว ลืมแกไปซะสนิทเลย!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đúng rồi, mèo con, tao hoàn toàn quên mất mày!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "哎呀，猫猫！我差点就把你忘掉了！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ach ja, Katerchen, ich hatte ganz vergessen, dass ich dich habe!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Oh, petit chat, je t'avais complètement oublié !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "SPRING_ACT1_EPILOUGE@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 1300010
L21_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "YOO_JIN_ALT_SPRING_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L21_1.m_Crash = 30
L22_1 = "가라! 저 녀석도 선도부장처럼 헤롱헤롱하게 만들어 버려!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "行け！　あいつも風紀委員長みたいにメロメロにさせちゃえ！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Now, go! Go turn him into mush like you did with the Student Guide Leader!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "去吧！讓那傢夥也像先鋒部隊長一樣被迷得神魂顛倒吧！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เอาล่ะ ลุยเลย! ทำให้เขากลายเป็นเจ้าทาส อย่างที่แกทำกับหัวหน้าสารวัตรนักเรียน!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Đi nào! Hãy biến cậu ta thành một kẻ ngốc như đã làm với Đội Trưởng Đội Sao Đỏ!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "来！伸出你的小肉球！把那小子也迷得晕头转向吧！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Jetzt geh! Mach ihn zu rührseligem Brei, wie du es mit der Leitenden Schülerlotsin gemacht hast!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vas-y ! Transforme-le en bouillie, comme tu l'as fait avec la tutrice-en-chef !"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
