L24_1 = "누, 누가 헤롱헤롱했다는 거냐?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "だ、誰がメロメロになっただと？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "W-who are you calling mush?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "妳、妳說誰被迷得神魂顛倒啊！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ระ-เรียกใครว่าเจ้าทาสกันน่ะ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "C-cậu đang gọi ai là kẻ ngốc thế hả?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "你、你说谁被迷得晕头转向了呢！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Wen nennst du hier rührseligen Brei?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "C'est moi que tu qualifies de bouillie ?"
L23_1.m_Talk_FRA = L24_1
