L29_1 = "L_M_I"
L28_1.m_Pos = L29_1
L29_1 = "설마, 선 채로 죽은 건가?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "まさか、立ったまま死んだとか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Oh no, did he die standing?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "不會吧，難道是站著死掉了嗎?"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ไม่นะ เขาตายตั้งยืนยังงั้นเหรอ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ồ không, cậu ấy chết đứng rồi à?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "不会吧，竟然可以忍受得住这种诱惑！？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Oh nein! Ist er stehend gestorben?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Oh, non, est-ce qu'il est mort debout ?"
L28_1.m_Talk_FRA = L29_1
