L30_1 = "SPRING_ACT1_EPILOUGE@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 1300010
L29_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_PRIDE"
L29_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L29_1.m_Pos = "L"
L29_1.m_Crash = 30
L30_1 = "과연, 싸나이에게 무릎을 꿇는 것은 수치!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "男にとってひざまずくのは恥だからな！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Of course, he's a real man who refuses to kneel!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "對男子漢大丈夫而言，妥協就是一種羞恥！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "น่าชื่นชมเหลือเกิน เขาเป็นคนจริงที่ไม่คิดจะคุกเข่าให้ใคร!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cậu ấy quả nhiên là một người đàn ông thực sự, không chịu quỳ gối!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "凯尔，你果然是一个永不妥协的真正男子汉！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Klar! Als echter Mann lässt er sich nicht in die Knie zwingen!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ça, c'est un homme, un vrai ! Jusqu'au bout, il refuse de s'agenouiller !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SPRING_ACT1_EPILOUGE@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 1300010
L30_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L30_1.m_Pos = "L"
L30_1.m_Crash = 30
L31_1 = "크으! 차디찬 얼굴 뒤로 열혈남아의 기질을 감추고 있었다니, 훌륭하군!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "くう！\nクールな顔の向こうに熱血男児の気質を隠していたとは、素晴らしい！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Ah! He was hiding such ferociousness behind his aloof mask. How commendable!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "哼哼！在冰冷的臉龐之後竟然隱藏著熱血男兒的氣質，真是厲害！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อา! ซ่อนความเกรี้ยวกราดเช่นนี้ไว้เบื้องหลังฉากหน้าที่หยิ่งผยอง ยอดจริงๆ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ah! Cậu ấy đang che giấu sự hung hăng sau chiếc mặt nạ xa cách của mình. Thật đáng khen làm sao!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "吼吼，在冰冷的脸庞之下竟然潜藏着如此热血的气质，太帅气了！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ah! Hinter seiner unnahbaren Maske verbarg er seine Wildheit. Sehr lobenswert!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Il cachait une incroyable ténacité derrière ses airs indifférents. C'est admirable !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
