L34_1 = "SPRING_ACT1_EPILOUGE@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 1300010
L33_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS"
L33_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L33_1.m_Pos = "C"
L34_1 = "죽긴 누가 죽습니까? 그리고 교실은 애완동물 출입금지입니다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "死んだって、誰がですか？　あと、教室にペットの持ち込みは禁止ですよ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "No, I didn't. And pets are not allowed in classrooms."
L33_1.m_Talk_ENG = L34_1
L34_1 = "妳說誰死了？而且禁止把寵物帶進教室。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ผมยังไม่ตายครับ แล้วก็ เราไม่อนุญาตให้นำสัตว์เลี้ยงเข้ามาในชั้นเรียน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Không, tôi không có. Và vật nuôi không được phép vào lớp học."
L33_1.m_Talk_VTN = L34_1
L34_1 = "你在说什么乱七八糟的，教室禁止宠物出入。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Von wegen. Und übrigens: Haustiere sind in Klassenzimmern nicht erlaubt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "C'est n'importe quoi. Et les animaux de compagnie ne sont pas autorisés en classe."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
