L36_1 = "SPRING_ACT1_EPILOUGE@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 1300010
L35_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "ADMIN_SCHOOL_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "......하지만 지금 같은 상황에선 길에 풀어 주기도 어렵겠죠. 우선 데리고 있도록 합시다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "……しかし、今のこの状況では外に放すことも難しいでしょう。\nひとまず保護しましょうか。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "... But the streets are too dangerous for him, too. We'll keep him with us for now."
L35_1.m_Talk_ENG = L36_1
L36_1 = "……但現在這種局勢，我們很難把牠丟回路邊，不然將貓交給我吧。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "... แต่ถนนข้างนอกก็อันตรายเกินไปนะ เอาเป็นว่าเราจะเลี้ยงมันไว้ก่อนก็แล้วกัน"
L35_1.m_Talk_THA = L36_1
L36_1 = "...Nhưng đường phố cũng quá nguy hiểm đối với nó. Chúng ta sẽ giữ nó ở với chúng ta lúc này."
L35_1.m_Talk_VTN = L36_1
L36_1 = ".....但是现在这个形势，在路上安置它也比较难，要不我先带着吧。"
L35_1.m_Talk_SCN = L36_1
L36_1 = " … Aber auf der Straße ist es zu gefährlich für ihn. Wir behalten ihn vorerst bei uns."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Les rues sont trop dangereuses pour lui, cependant. Nous le garderons donc avec nous jusqu'à nouvel ordre."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "SPRING_ACT1_EPILOUGE@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 1300010
L36_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L36_1.m_bWaitClick = true
