L36_1.m_Face = "UNIT_SURPRISE"
L37_1 = "YOO_JIN_ALT_SPRING_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L36_1.m_Crash = 30
L37_1 = "어, 엇......? 교장선생님?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "え、えっ……？　校長先生？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Err, err? Mr. Principal?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "噢什…？校長大人？！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เอ่อ เอ่อ? คุณครูใหญ่?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ơ, ơ? Thầy Hiệu Trưởng?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "噢...噢？是校长大人？！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hä? Herr Rektor?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Oh ?! Monsieur le principal ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
