L39_1 = "ADMIN_SCHOOL_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "하하, 다들 여기 모여 있었네요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "はは、皆さんこちらに集まっていましたか。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Hah hah, you were all here."
L38_1.m_Talk_ENG = L39_1
L39_1 = "哈哈，大家都聚在這裡呢。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ฮะฮะ อยู่กันพร้อมหน้าเลยนะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ha ha, tất cả các em đều ở đây."
L38_1.m_Talk_VTN = L39_1
L39_1 = "哈哈，大家原来都聚在这里呢。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Haha, ihr wart alle hier."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ha ha ha, vous étiez là."
L38_1.m_Talk_FRA = L39_1
