L39_1.m_Face = "UNIT_LAUGH"
L39_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L40_1 = "C_R_M_I"
L39_1.m_Pos = L40_1
L40_1 = "교장선생님! 좋은 아침!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "校長先生！　おはよう！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Mr. Principal! Good morning!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "校長！早上好！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อรุณสวัสดิ์ค่ะ! คุณครูใหญ่!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Thầy Hiệu Trưởng! Buổi sáng tốt lành!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "校长！早上好！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Herr Rektor! Guten Morgen!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Monsieur le principal ! Bonjour !"
L39_1.m_Talk_FRA = L40_1
