L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 1300010
L41_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "ADMIN_SCHOOL_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "고맙군요. 아이리 양도 좋은 아침입니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ありがとう、アイリさん。おはようございます。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Thank you. Good morning to you too, Irie."
L41_1.m_Talk_ENG = L42_1
L42_1 = "謝謝，艾莉同學，妳也早啊。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "อื้ม อรุณสวัสดิ์นะ ไอรี่"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cảm ơn em. Em cũng có buổi sáng tốt lành nhé, Irie."
L41_1.m_Talk_VTN = L42_1
L42_1 = "谢谢，艾力小姐，你也早上好哇。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Danke. Dir auch einen guten Morgen, Irie."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Bonjour, Irie."
L41_1.m_Talk_FRA = L42_1
