L44_1.m_Face = "UNIT_HATE"
L44_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L44_1.m_Pos = "R"
L45_1 = "아이리, 교장 선생님과 하이파이브로 인사하지 말라고 했을 텐데?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "アイリ、校長先生とハイタッチで挨拶するなと言ったはずだが？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Irie, I told you not to hi-five the Mr. Principal."
L44_1.m_Talk_ENG = L45_1
L45_1 = "艾莉，妳該不會是用擊掌來和校長打招呼吧?"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ไอรี่ ฉันบอกแล้วไม่ใช่เหรอว่าอย่าไฮไฟว์คุณครูใหญ่น่ะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Irie, tôi đã nói với cậu là không được chào đập tay với Hiệu Trưởng rồi mà."
L44_1.m_Talk_VTN = L45_1
L45_1 = "艾力，你该不会是用击掌的方式来和校长打招呼的吧?"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Irie, du sollst den Herrn Rektor doch nicht abklatschen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Irie, je t'ai déjà dit de ne pas taper dans la main du principal pour le saluer."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SPRING_ACT1_EPILOUGE@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 1300010
L45_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L45_1.m_Pos = "L"
L46_1 = "크흠! 오늘도 어둠의 흑막 같은 분위기가 물씬 풍기는군, 보스!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ごほん！　今日も闇の黒幕のようなオーラが漂っているな、ボス！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Hmm, you look as sinister as usual, like the boss of the darkness that you are."
L45_1.m_Talk_ENG = L46_1
L46_1 = "嗯！你今天也充滿了黑暗的氣息呢，老師！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฮืมม ดูชั่วร้ายเหมือนเคย สมเป็นบอสที่บงการทุกอย่างจากความมืดจริงๆ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Hừm, trông thầy vẫn nham hiểm như mọi khi, giống như ông trùm xã hội đen vậy."
L45_1.m_Talk_VTN = L46_1
L46_1 = "哼！不愧是老大，今天也散发着令人战栗的黑暗气息呢！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Hm … Sie sehen finster aus wie immer, wie der Herr der Finsternis."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Vous avez l'air aussi sinistre que d'ordinaire, ce qui convient au boss des ténèbres que vous êtes."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
