L48_1 = "SPRING_ACT1_EPILOUGE@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 1300010
L47_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_SERIOUS"
L47_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L47_1.m_Pos = "C"
L48_1 = "보스가 아니라 교장 선생님입니다. 호칭에 주의하십시오."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "ボスじゃなくて校長先生です。呼び方には注意してください。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Not a boss; Mr. Principal. Please address him properly."
L47_1.m_Talk_ENG = L48_1
L48_1 = "不是老師，是校長。請妳注意稱呼。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ไม่ใช่บอส คุรครูใหญ่ต่างหาก เธอต้องเรียกเขาด้วยความเคารพสิ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Không phải là ông trùm; là thầy Hiệu Trưởng. Hãy xưng hô đúng cách với thầy đi nào."
L47_1.m_Talk_VTN = L48_1
L48_1 = "不是老大，是校长。请你注意称呼，西恩小姐。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Er ist nicht Herr der Finsternis, sondern Herr Rektor. Bitte sprich ihn korrekt an."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ce n'est pas un « boss », c'est notre principal. Adressez-vous à lui correctement."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
