L50_1 = "SPRING_ACT1_EPILOUGE@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 1300010
L49_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "ADMIN_SCHOOL_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "하하, 괜찮습니다. 모두들 한결 같이 기운이 넘쳐 보여서 저도 기분이 좋군요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "はは、大丈夫ですよ。みんながいつもどおり元気そうで、私も嬉しいです。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Hah hah, it’s okay. I'm glad you all look so energetic today."
L49_1.m_Talk_ENG = L50_1
L50_1 = "哈哈，沒關係。看到大家這麼有精神，我也很高興。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฮะฮะ ไม่เป็นไรหรอกนะ ฉันดีใจนะ ที่ทุกคนดูร่าเริงดีในวันนี้"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ha ha, không sao đâu. Thầy rất vui vì ngày hôm nay nhìn tất cả các em đều tràn đầy năng lượng."
L49_1.m_Talk_VTN = L50_1
L50_1 = "哈哈，没关系。大家看起来都精神抖擞，我看了也很高兴。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Haha, ist schon gut. Ich bin froh, dass ihr heute alle so munter ausseht."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ha ha ha, ce n'est rien. Je suis heureux de vous voir aussi énergétiques aujourd'hui."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SPRING_ACT1_EPILOUGE@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 1300010
L50_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_LAUGH"
L51_1 = "SEO_YOON_ALT_SPRING_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "그런데 왠 일로 여기까지 내려오셨어요, 선생님?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "ところで先生、ここにはどんな用事で来られたんですか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "By the way, what brings you all the way down here, Mr. Principal?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "不過您為什麼會來這裡呢，老師？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ว่าแต่ มีธุระถึงลงมาที่นี่เหรอคะ คุณครูใหญ่?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nhân tiện, điều gì đã đưa ngài đến đây vậy, thưa Hiệu Trưởng?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "不过您为什么会走到这里呢，老师?"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Was führt Sie den ganzen Weg hierher, Herr Rektor?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Au fait, qu'est-ce qui vous amène ici, monsieur le principal ?"
L50_1.m_Talk_FRA = L51_1
