L2_1 = "SPRING_ACT1_EPILOUGE@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 1300010
L1_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "UNIT_IDLE"
L1_1.m_Face = L2_1
L2_1 = "SEO_YOON_ALT_SPRING_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "건강 때문에 평소엔 바람도 잘 안 쐬셨잖아요. 아직 날씨도 쌀쌀한데......"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "健康のために、普段はあまり外にもでないでしょう？\nまだ肌寒いですし……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I thought you shouldn't be exposed to cold air because of your health. It's still chilly outside."
L1_1.m_Talk_ENG = L2_1
L2_1 = "因為您身體的關係，您平常不能吹風啊，最近天氣又很冷..."
L1_1.m_Talk_TWN = L2_1
L2_1 = "สุขภาพไม่ค่อยดีแบบนี้ คุณไม่ควรเจออากาศเย็นนะคะ ข้างนอกยังหนาวอยู่เลย"
L1_1.m_Talk_THA = L2_1
L2_1 = "Em nghĩ thầy không nên tiếp xúc với không khí lạnh vì sức khỏe của thầy. Ngoài trời vẫn còn lạnh lắm."
L1_1.m_Talk_VTN = L2_1
L2_1 = "您的身体，平时待着不怎么能吹风，最近天气还冷..."
L1_1.m_Talk_SCN = L2_1
L2_1 = "Sie sollten Ihre Gesundheit nicht an der kalten Luft aufs Spiel setzen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je croyais que vous ne deviez pas sortir dans le froid à cause de vos problèmes de santé. Il y a encore du vent aujourd'hui."
L1_1.m_Talk_FRA = L2_1
