L4_1 = "SPRING_ACT1_EPILOUGE@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 1300010
L3_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "ADMIN_SCHOOL_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "그래요. 하지만 오늘은 특별한 날이라서요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そうですね。でも今日は特別な日なんです。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Yes, but today's a special day."
L3_1.m_Talk_ENG = L4_1
L4_1 = "沒錯，不過今天是特別的日子。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "มันก็จริง แต่วันนี้เป็นวันพิเศษ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đúng vậy, nhưng hôm nay là một ngày đặc biệt."
L3_1.m_Talk_VTN = L4_1
L4_1 = "嗯，是的，但是今天是特别的日子。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Na ja, heute ist ein besonderer Tag."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Oui, mais cette journée est spéciale."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "SPRING_ACT1_EPILOUGE@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 1300010
L4_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "ADMIN_SCHOOL_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "다들 알고 계시겠지만, 이 교사로 등교하는 것도 오늘이 마지막입니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "みんなも知ってのとおり、この校舎に登校するのは今日で最後ですからね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "As you know, today is our last day in this school."
L4_1.m_Talk_ENG = L5_1
L5_1 = "大家應該都知道了吧，今天也是我最後一次以老師的身份到學校來了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "อย่างที่เธอรู้ วันนี้เป็นวันสุดท้ายของโรงเรียนแห่งนี้"
L4_1.m_Talk_THA = L5_1
L5_1 = "Như các em đã biết, hôm nay là ngày cuối cùng của chúng ta trong ngôi trường này."
L4_1.m_Talk_VTN = L5_1
L5_1 = "大家应该都知道了吧，今天也是我最后一次以这老师的身份到学校来了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wie ihr wisst, ist heute der letzte Schultag."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Comme vous le savez, c'est notre dernier jour dans cette école."
L4_1.m_Talk_FRA = L5_1
