L11_1 = "ADMIN_SCHOOL_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "통신문에 적힌 대로, 내일부턴 차원 함선 내부에 마련된 이동 교실에서 생활하게 될 거에요."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "お便りにも書いたとおり、明日からは次元艦船の内部に作られた移動教室で勉強することになります。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "As it's written in the latest newsletter, you will all be studying in the mobile classroom inside the dimensional ship, starting tomorrow."
L10_1.m_Talk_ENG = L11_1
L11_1 = "正如通知上所說的，從明天開始，我們要在次元艦船內部的移動教室裡度過了。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ก็อย่างที่เขียนไว้ในจดหมายข่าวฉบับล่าสุด พวกเธอจะต้องเข้าเรียนในชั้นเรียนเคลื่อนที่ซึ่งอยู่ในยานข้ามมิติ ตั้งแต่วันพรุ่งนี้เป็นต้นไป"
L10_1.m_Talk_THA = L11_1
L11_1 = "Như được viết trong bản tin mới nhất, tất cả các em sẽ học trong lớp học di động bên trong chiến hạm đa chiều, bắt đầu từ ngày mai."
L10_1.m_Talk_VTN = L11_1
L11_1 = "正如通知上所说的，从明天开始，我们要在次元舰船内部的移动教室里度过了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wie im letzten Newsletter geschrieben, werdet ihr alle ab morgen im mobilen Klassenzimmer im Inneren des Dimensionsschiffs lernen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Vous l'avez certainement lu dans notre dernier courrier, mais vous étudierez à bord du vaisseau dimensionnel à partir de demain."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SPRING_ACT1_EPILOUGE@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 1300010
L11_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "ADMIN_SCHOOL_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "어떻게든 이 교정을 지켜내고 싶었지만, 침식 현상의 확산이 너무 빨라 더 이상은 어렵게 됐습니다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "何とかこの学校を守りたかったのですが、\n侵食現象の広がりが速すぎて限界を迎えました。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I wanted to protect this campus, but the Counterside Effect has been spreading too quickly."
L11_1.m_Talk_ENG = L12_1
L12_1 = "無論我們多麼想保住這個校園，但侵蝕現象的擴散太快，很難再堅持下去。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันเองก็อยากจะปกป้องที่แห่งนี้ไว้ แต่ปรากฏการณ์เคาน์เตอร์ไซด์แพร่กระจายอย่างรวดเร็วเหลือเกิน"
L11_1.m_Talk_THA = L12_1
L12_1 = "Thầy cũng muốn bảo vệ khuôn viên này, nhưng Hiệu ứng Counterside đã lây lan quá nhanh."
L11_1.m_Talk_VTN = L12_1
L12_1 = "无论我们多么想保住这个校园，但侵蚀现象的扩散太快，很难再坚持下去了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich wollte diesen Campus schützen, aber der Counterside-Effekt hat sich zu schnell ausgebreitet."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je voulais protéger ce campus, mais l'effet du Contremonde se répand trop rapidement."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SPRING_ACT1_EPILOUGE@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 1300010
L12_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "ADMIN_SCHOOL_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "미안합니다. 노력해 봤지만 지금은 이게 최선인 것 같군요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "申し訳ありません。\n努力しましたがここまでのようです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I'm sorry. This is the best I can do for now."
L12_1.m_Talk_ENG = L13_1
L13_1 = "對不起，雖然我已經盡力了，但這是目前最好的方法了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ต้องขอโทษด้วย ฉันทำได้ดีที่สุดแค่นี้จริงๆ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Xin lỗi. Đây là điều tốt nhất thầy có thể làm bây giờ."
L12_1.m_Talk_VTN = L13_1
L13_1 = "对不起，虽然都很不舍，但看来这可能是目前最好的处理方法了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Tut mir leid … Mehr kann ich im Moment nicht tun."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je suis navré. C'est le mieux que je puisse faire pour l'instant."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SPRING_ACT1_EPILOUGE@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 1300010
L13_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_PRIDE"
L13_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L13_1.m_Pos = "R"
L14_1 = "가르치는 이와 배우는 사람이 있다면 내게는 그곳이 학교다. 상관없어."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "教える者と学ぶ者さえいればそこが学校だ。場所はどこでも構わない。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I don't care where I learn, so long as I can learn."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但只要有人願意教，有人願意學，那裡就是一間學校，所以不需要在意。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันไม่สนใจหรอกค่ะ ว่าจะได้เรียนหนังสือที่ไหน ตราบใดที่ยังได้ความรู้"
L13_1.m_Talk_THA = L14_1
L14_1 = "Em không quan tâm mình học ở đâu, miễn là có thể học được."
L13_1.m_Talk_VTN = L14_1
L14_1 = "哪里有愿意教书的人和愿意学习的人，哪里就是学校，所以，没关系的，校长。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Mir ist egal, wo ich lerne, solange ich lernen kann."
L13_1.m_Talk_DEU = L14_1
L14_1 = "L'endroit où j'apprends m'importe peu, tant que je peux apprendre."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "SPRING_ACT1_EPILOUGE@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 1300010
L14_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_PRIDE"
L14_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L14_1.m_Pos = "L"
L15_1 = "저희는 평범한 학생이 아닌 소명을 짊어진 카운터들. 그런 일로 어리광 피울 순 없습니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "僕たちは平凡な生徒ではなく、使命を背負ったカウンターです。\nそのようなことで甘えることはできません。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "We're not ordinary students, but Counters on a mission. We won't complain about such trivial matters."
L14_1.m_Talk_ENG = L15_1
L15_1 = "我們不是普通的學生，而是背負著使命的制裁者，不能因為這種事撒嬌抱怨。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "พวกเราไม่ใช่นักเรียนธรรมดา แต่เป็นเคาน์เตอร์ผู้ปฏิบัติภารกิจ เราไม่ได้อยู่ในฐานะที่จะบ่นกับเรื่องเล็กๆ น้อยๆ แบบนั้นหรอกครับ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Bọn em không phải là những học sinh bình thường, mà là các Counter đang thực hiện nhiệm vụ. Bọn em sẽ không phàn nàn về những vấn đề nhỏ nhặt như vậy đâu."
L14_1.m_Talk_VTN = L15_1
L15_1 = "我们不是平凡的学生，而是背负着使命的制裁者，不能因为这种事撒娇抱怨了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Wir sind keine gewöhnlichen Schüler, sondern Counter auf einer Mission. Wegen solcher Trivialitäten werden wir uns nicht beschweren."
L14_1.m_Talk_DEU = L15_1
L15_1 = "On n'est pas des élèves ordinaires, mais des Counters chargés d'une mission. On ne se plaindra pas de détails aussi triviaux."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SPRING_ACT1_EPILOUGE@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 1300010
L15_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_PRIDE"
L16_1 = "YOO_JIN_ALT_SPRING_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "R"
L16_1 = "건물 같은 게 뭐 중요하겠어. 운동장이면 몰라도."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "建物は重要じゃない。グラウンドならともかくな。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Buildings don't matter... Maybe except for the stadium."
L15_1.m_Talk_ENG = L16_1
L16_1 = "建築物什麼的，又有什麼重要的呢？我甚至不在乎操場呢。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ตึกพวกนี้ไม่ใช่เรื่องสำคัญหรอกค่ะ... เอ่อ อาจจะยกเว้นสนามกีฬาไว้อันนึง"
L15_1.m_Talk_THA = L16_1
L16_1 = "Nhà không thành vấn đề... Có lẽ là ngoại trừ sân vận động."
L15_1.m_Talk_VTN = L16_1
L16_1 = "建筑物之类的东西有什么重要呢。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Gebäude spielen keine Rolle … Na ja, vielleicht mit Ausnahme des Stadions."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ces bâtiments ne sont pas importants... à part le stade, peut-être."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 1300010
L16_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L16_1.m_bWaitClick = false
