L18_1 = "ADMIN_SCHOOL_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "다들 이해해 줘서 고맙습니다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "皆さん、理解してくれてありがとう。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Everyone, thank you for your understanding."
L17_1.m_Talk_ENG = L18_1
L18_1 = "謝謝大家願意理解。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ขอบคุณที่เข้าใจนะ ทุกคน"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cảm ơn tất cả các em đã thông cảm."
L17_1.m_Talk_VTN = L18_1
L18_1 = "谢谢大家的理解。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich danke euch allen für euer Verständnis."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Merci de votre compréhension à tous."
L17_1.m_Talk_FRA = L18_1
