L19_1 = "SPRING_ACT1_EPILOUGE@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 1300010
L18_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "ADMIN_SCHOOL_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "앞으로 얼마나 이 학교를 이끌어나갈 수 있을지 모르겠지만......"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "いつまでこの学校を導いていけるかわかりませんが……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I don't know how longer I can keep the school going,"
L18_1.m_Talk_ENG = L19_1
L19_1 = "我不知道今後能帶領這所學校的大家走多遠……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ฉันไม่รู้ว่าฉันจะดูแลโรงเรียนนี้ต่อไปได้อีกนานแค่ไหน"
L18_1.m_Talk_THA = L19_1
L19_1 = "Thầy không biết mình có thể duy trì trường học được bao lâu nữa,"
L18_1.m_Talk_VTN = L19_1
L19_1 = "我不知道今后能带领这所学校走多远......"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ich weiß nicht, wie lange ich die Schule noch am Laufen halten kann."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Je ne sais pas combien de temps je pourrai encore faire tourner cette école,"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "SPRING_ACT1_EPILOUGE@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 1300010
L19_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "ADMIN_SCHOOL_NULL_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "저 역시 마지막까지 여러분이 즐거운 학창생활을 보낼 수 있도록 최선을 다하겠습니다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "最後まで皆さんが楽しい学生生活を送れるように最善を尽くします。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "but I'll do my best to help you enjoy your student life."
L19_1.m_Talk_ENG = L20_1
L20_1 = "但我一定會努力到最後，讓大家過上快樂平穩的學生生活。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่ฉันจะพยายามอย่างเต็มที่ เพื่อให้พวกเธอได้มีความสุขกับชีวิตนักเรียน"
L19_1.m_Talk_THA = L20_1
L20_1 = "nhưng thầy sẽ cố gắng hết sức để giúp các em tận hưởng cuộc sống học sinh của mình."
L19_1.m_Talk_VTN = L20_1
L20_1 = "但我一定竭尽全力，让大家过上快乐平稳的学习生活。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Aber ich werde mein Bestes geben, damit ihr Freude an eurem Schülerdasein habt."
L19_1.m_Talk_DEU = L20_1
L20_1 = "mais je ferai tout mon possible pour vous permettre de profiter de votre vie d'étudiantes."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "SPRING_ACT1_EPILOUGE@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 1300010
L20_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS"
L21_1 = "YOO_JIN_ALT_SPRING_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L21_1 = "그런데 우리가 탈 차원 함선은 어디로 가는 거야?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "で、俺たちが乗る次元艦船はどこに向かうんだ？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "By the way, where will our dimensional ship be headed to?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "但是我們乘坐的次元艦船要開到哪裡啊？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ว่าแต่ ยานข้ามมิติของเราจะเดินทางไปที่ไหนกันเหรอคะ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nhân tiện, chiến hạm đa chiều của chúng ta sẽ đi đến đâu vậy ạ?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "不过话说，我们乘坐的次元舰船去往哪里啊?"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Übrigens, wohin wird unser Dimensionsschiff fliegen?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Au fait, où va notre vaisseau dimensionnel ?"
L20_1.m_Talk_FRA = L21_1
