L22_1 = "SPRING_ACT1_EPILOUGE@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 1300010
L21_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_DESPAIR"
L22_1 = "YOO_JIN_ALT_SPRING_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L22_1 = "아니, 뭐, 고양이를 기를 수 있는 데인지 궁금해서 그러는 건 아닌데...... 함선은 중요한 무기니까......"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "いや、猫が飼える環境なのかを気にしているわけじゃなくて……\n艦船は大事な武器だから……"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Well, I'm not asking because I want to know if I can keep this cat; I'm asking because ships are important weapons..."
L21_1.m_Talk_ENG = L22_1
L22_1 = "沒有啦，我不是好奇那裡是不是可以養貓...因為艦船是重要的武器嘛..."
L21_1.m_Talk_TWN = L22_1
L22_1 = "เอ่อ ที่ถามนี่ ไม่ใช่เพราะว่าอยากรู้ว่าเลี้ยงแมวได้รึเปล่าหรอกนะคะ แต่ เพราะยานรบน่ะเป็นอาวุธสำคัญไม่ใช่เหรอ..."
L21_1.m_Talk_THA = L22_1
L22_1 = "Em không hỏi vì muốn biết liệu em có thể nuôi con mèo này hay không đâu; em hỏi vì tàu là vũ khí quan trọng..."
L21_1.m_Talk_VTN = L22_1
L22_1 = "啊不是，我不是好奇那里是不是可以养猫...因为舰船是重要的武器嘛哈哈..."
L21_1.m_Talk_SCN = L22_1
L22_1 = "… Ich frage das nicht, um zu erfahren, ob ich diesen Kater behalten kann – sondern, weil Schiffe wichtige Waffen sind."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je ne pose pas la question pour savoir si je peux garder ce chat, mais parce que ces vaisseaux sont des armes puissantes..."
L21_1.m_Talk_FRA = L22_1
