L25_1.m_Pos = "L"
L26_1 = "아니, 방금 질문은 아주 좋았다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "いや、すごくいい質問だった。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "No. I liked that question."
L25_1.m_Talk_ENG = L26_1
L26_1 = "不，剛才的提問非常好。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่ผิดเลย ฉันชอบคำถามนั่นด้วยซ้ำ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Không, tôi thích câu hỏi đó."
