L26_1 = "不，刚才的提问非常好。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Nein, nein, mir gefällt die Frage."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Pour rien. Ta question m'a plu."
L25_1.m_Talk_FRA = L26_1
