L26_1.m_Pos = "R"
L27_1 = "저도 같은 생각입니다. 유진 양의 학습 능력을 재검증할 필요는 없겠군요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "僕も同感です。シロコさんの学習能力を再検証する必要はなさそうですね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "So did I. Eujin, your learning ability doesn't need reevaluation."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我也這麼認為，看來不需要再驗證小劉珍的學習能力了。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ผมเองก็เช่นกัน ยูจิน ทักษะการเรียนรู้ของคุณไม่ต้องรับการประเมินใหม่แล้วล่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi cũng vậy. Eujin, khả năng học tập của cậu không cần phải đánh giá lại đâu."
L26_1.m_Talk_VTN = L27_1
L27_1 = "我也是这样在思考的，所以不需要再验证刘珍的学习能力了。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Mir auch. Eujin, deine Lernfähigkeit muss nicht neu bewertet werden."
L26_1.m_Talk_DEU = L27_1
L27_1 = "À moi aussi. Eujin, votre capacité d'apprentissage ne nécessite pas de réévaluation."
L26_1.m_Talk_FRA = L27_1
