L31_1 = "哈哈，妳當然好奇。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฮะฮะ ได้สิ เธออยากรู้สินะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ha ha. Tất nhiên, các em đều tò mò mà nhỉ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "哈哈，当然可以抱有好奇。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Haha … Natürlich seid ihr neugierig."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ha ha. Vous êtes curieuse, c'est normal."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "SPRING_ACT1_EPILOUGE@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 1300010
L31_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "ADMIN_SCHOOL_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "내일 새로 완성될 차원함선에 탑승하는 순간부터 여러분은 카운터 아카데미의 졸업반이자 견습 전투원으로 대우받게 될 겁니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "明日完成する次元艦船に搭乗した瞬間から、\n皆さんはカウンターアカデミーの卒業組であり、見習い戦闘員として扱われることになります。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "The moment you get on the new dimensional ship that will begin operating tomorrow, you'll become senior students at the Academy, and also training combatants."
L31_1.m_Talk_ENG = L32_1
L32_1 = "明天，在登上新造次元艦船的那一刻起，妳們就會成為制裁者學院的畢業生，接受見習戰鬥員的待遇。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เมื่อพวกเธอขึ้นยานข้ามมิติลำใหม่ที่จะเริ่มออกปฏิบัติการตั้งแต่พรุ่งนี้ เธอก็จะได้เป็นนักเรียนรุ่นพี่ที่วิทยาลัย และรับตำแหน่งเป็นทหารฝึกหัดด้วย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Thời điểm các em tiến vào chiến hạm đa chiều mới sẽ bắt đầu hoạt động vào ngày mai, các em cũng sẽ trở thành học sinh cuối cấp tại Học Viện, và cũng là nơi đào tạo các chiến binh."
L31_1.m_Talk_VTN = L32_1
L32_1 = "从明日乘坐新造的次元舰船的那一刻起，大家将享受制裁者学院毕业班见习战斗员的待遇。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Sobald ihr das neue Dimensionsschiff betretet, das morgen in Betrieb genommen wird, werdet ihr zu Oberschülern der Akademie – und damit auch zu Trainingskämpfern."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Quand vous monterez à bord du vaisseau dimensionnel qui sera mis en activité demain, vous entrerez dans le dernier cycle d'études de l'Académie, et vous commencerez également votre entraînement de combattants."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "SPRING_ACT1_EPILOUGE@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 1300010
L32_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "ADMIN_SCHOOL_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "물론, 바로 격전지에 파견되지는 않을 거에요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "もちろん、すぐ激戦地に派遣されることはありません。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Of course, that doesn't mean you'll be fighting out on the battlefield right away."
L32_1.m_Talk_ENG = L33_1
L33_1 = "當然，大家不會馬上被派遣到前線。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แน่นอนว่าเธอยังจะไม่ได้ออกไปต่อสู้ในสนามรบทันทีหรอกนะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tất nhiên, chuyện đó không có nghĩa là các em sẽ chiến đấu trên chiến trường ngay lập tức."
L32_1.m_Talk_VTN = L33_1
L33_1 = "当然，大家不会马上被派遣到侵蚀战前线。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das bedeutet natürlich nicht, dass ihr gleich auf dem Schlachtfeld kämpfen werdet."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Bien sûr, cela ne signifie pas que vous serez immédiatement envoyés sur le champ de bataille."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SPRING_ACT1_EPILOUGE@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 1300010
L33_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "ADMIN_SCHOOL_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "우리들의 첫 번째 임무는 바로 구출작전."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "私たちの初めての任務は救出作戦です。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Our first mission is a rescue mission."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我們的首要任務就是營救作戰。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ภารกิจแรกของเราคือภารกิจช่วยชีวิต"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhiệm vụ đầu tiên của chúng ta là một nhiệm vụ giải cứu."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我们的首要任务就是营救作战。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Unsere erste Mission ist eine Rettungsmission."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Notre première mission est un sauvetage."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "SPRING_ACT1_EPILOUGE@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 1300010
L34_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "ADMIN_SCHOOL_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "지난번, 제 4종 침식체가 학교를 습격했을 때 사라진 학생회장을 구출하는 겁니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "以前、第4種侵食体が学校を襲撃した時に\n行方不明になった生徒会長を救出するのです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "We'll rescue the Student President who disappeared when the Category 4 C.O. attacked the Academy the last time."
L34_1.m_Talk_ENG = L35_1
L35_1 = "例如：上次4類侵蝕體突襲學校時，要救出當時因此消失的學生會長。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เราจะไปช่วยเหลือประธานนักเรียนที่หายตัวไป ตอนที่วัตถุคอร์รัปต์คลาส 4 โจมตีวิทยาลัยเราในคราวที่ผ่านมา"
L34_1.m_Talk_THA = L35_1
L35_1 = "Chúng ta sẽ giải cứu Chủ Tịch Hội Học Sinh, người đã biến mất khi V.T.B.A.M. Loại 4 tấn công Học Viện vào lần trước."
L34_1.m_Talk_VTN = L35_1
L35_1 = "我们将首先对上次四级侵蚀体突袭学校时，消失的学生会会长展开搜救工作。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wir werden die Schülerpräsidentin retten, die verschwand, als das C. O. der Kategorie 4 das letzte Mal die Akademie angriff."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Nous secourrons la présidente du Conseil, qui a disparu lors de l'attaque de l'O.C. catégorie 4 contre l'Académie."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "SPRING_ACT1_EPILOUGE@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 1300010
L35_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_SURPRISE"
L35_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L35_1.m_Pos = "C"
L35_1.m_Crash = 30
L36_1 = "그게 정말입니까? 하지만 학생회장은 그때 분명......"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "それは本当ですか？　しかし、あの時生徒会長は確か……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Really? But the Student President..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "學生會長的事情是真的嗎？不過，學生會長當時明明……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "จริงเหรอครับ? แต่ประธานนักเรียน..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Thật ư? Nhưng Chủ Tịch Hội Học Sinh..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "真的吗？不过，会长当时明明......"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wirklich? Aber die Schülerpräsidentin …"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Vraiment ? Mais la présidente du Conseil..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
