L38_1 = "SPRING_ACT1_EPILOUGE@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 1300010
L37_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "ADMIN_SCHOOL_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "그래요. 우리를 지키는 대신 침식체와 함께 양자터널로 빨려 들어갔죠."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "はい。私たちを守ろうと侵食体と共に量子トンネルに吸い込まれました。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Yes, she saved us and got sucked into that quantum tunnel along with the C.O.'s."
L37_1.m_Talk_ENG = L38_1
L38_1 = "是的，當時她為了保護我們，和侵蝕體一起被吸進了量子隧道。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ใช่แล้ว เธอช่วยพวกเราไว้ และถูกดูดเข้าไปในอุโมงค์ควอนตัมพร้อมกับวัตถุคอร์รัปต์"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đúng vậy, em ấy đã cứu chúng ta và bị hút vào đường hầm lượng tử cùng với V.T.B.A.M."
L37_1.m_Talk_VTN = L38_1
L38_1 = "是的，她当时为了守卫我们，连同侵蚀体一起被卷入了量子隧道。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sie hat uns gerettet und wurde zusammen mit den C. O.s in den Quantumtunnel gesaugt."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Effectivement, après nous avoir sauvés, elle a été aspirée dans un tunnel quantique avec les O.C."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SPRING_ACT1_EPILOUGE@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 1300010
L38_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "ADMIN_SCHOOL_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "하지만 전투훈련 고문이신 힐데 교감님께서 차원 흔적을 추적한 끝에, 특정 고심도 좌표에서 학생회장과 동일한 파형의 CRF를 발견하셨다고 합니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "しかし、戦闘訓練顧問のヒルデ教頭が次元痕跡を追跡した結果、\nある高深度座標から生徒会長と同じ波形のCRFを発見したそうです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But our Combat Training Advisor and Vice-principal Hilde followed their dimensional traces and detected the same CRF as the Student President's on certain coordinates at great depth."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但戰鬥訓練顧問希爾德在追蹤空間軌跡時，發現在次元邊界特定的中心座標上，出現與學生會長相同的波形的CRF。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ที่ปรึกษาด้านการฝึกต่อสู้และรองอาจารย์ใหญ่ของเรา ฮิลเด้ ได้แกะร่องรอยมิติเหล่านั้น และตรวจพบ CRF รูปแบบเดียวกับประธานนักเรียน ในพิกัดแห่งหนึ่ง ณ จุดที่ลึกมากๆ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng Cố Vấn Huấn Luyện Chiến Đấu và Phó Hiệu Trưởng Hilde của chúng ta đã lần theo dấu vết không gian và phát hiện một CRF giống như của Chủ Tịch Hội Học Sinh ở một tọa độ độ sâu nhất định."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但是我们的副校长兼战斗训练顾问希尔德老师，在追踪空间轨迹时，在次元边界特定的深处坐标上，发现了与学生会会长相同波形的CRF。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber Hilde, unsere Beraterin für Kampfausbildung und stellvertretende Schulleiterin, folgte ihren Dimensionsspuren. Sie entdeckte bei bestimmten Koordinaten in großer Tiefe dieselbe CRS wie die der Schülerpräsidentin."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Cependant, Hilde, notre instructrice de combat et vice-principale, a suivi ses traces dimensionnelles et elle a détecté le FRC de la présidente du Conseil à des coordonnées très profondes."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
