L42_1 = "호오, 부두목이......?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ほう、アンダーボスが……？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Oooh, the Deputy Boss has?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "哦，也就是說她……?"
L41_1.m_Talk_TWN = L42_1
L42_1 = "โอ้วว รองบอสทำได้เหรอเนี่ย?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Oooh, Trùm Phó làm được vậy luôn hả?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "哦？二把手她？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Das hat die stellvertretende Chefin getan?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Oooh, la vice-boss a fait ça ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "SPRING_ACT1_EPILOUGE@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 1300010
L42_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "SEO_YOON_ALT_SPRING_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "L"
L43_1 = 40
L42_1.m_Crash = L43_1
L43_1 = "미나를 찾아냈다고요? 정말이죠?!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ミナを見つけたんですか？　本当ですね！？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You've found Mina? Are you serious?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "找到米娜了嗎? 真的嗎？！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "คุณเจอตัวมีนาแล้วเหรอ? จริงเหรอคะ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cô ấy đã tìm thấy Mina sao? Thầy nói thật chứ?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "意思是找到了米娜? 真的吗？！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Mina wurde gefunden? Ist das Ihr Ernst?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Vous avez retrouvé Mina ? Pour de vrai ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
