L45_1 = "SPRING_ACT1_EPILOUGE@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 1300010
L44_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "ADMIN_SCHOOL_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "네. 실종으로부터 꽤 시간이 지나긴 했지만, 학생회장이라면......"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ええ。失踪してからかなり時間が経ってしまいましたが、生徒会長なら……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Yes. It's been a while since she disappeared, but the Student President..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "是的，雖然從失蹤開始已經過了很長一段時間，但學生會長……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ใช่แล้ว เธอหายตัวไปนานพอสมควรแล้ว แต่ประธานนักเรียน..."
L44_1.m_Talk_THA = L45_1
L45_1 = "Đúng vậy. Em ấy biến mất cũng được một thời gian rồi, nhưng Chủ Tịch Hội Học Sinh..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "是的，虽然从失踪开始到现在时间已经过了许久，但我相信学生会会长她......"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ja. Es ist schon eine Weile her, dass sie verschwunden ist, aber die Schülerpräsidentin …"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oui. Elle a disparu depuis longtemps, mais la présidente du Conseil..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SPRING_ACT1_EPILOUGE@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 1300010
L45_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "ADMIN_SCHOOL_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "미나 양이라면 반드시 살아 있을 거라고, 전 믿고 있습니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ミナさんなら必ず生きていると、私は信じています。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Mina is strong enough to be alive, or so I believe."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我相信米娜同學一定會活著的。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มีนา เป็นคนที่แข็งแกร่งพอ เพราะฉะนั้นเธอจะต้องมีชีวิตอยู่แน่ๆ ฉันเชื่ออย่างนั้น"
L45_1.m_Talk_THA = L46_1
L46_1 = "Mina đủ mạnh mẽ để sống sót, hoặc thầy tin là vậy."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我相信米娜小姐，一定会活着的。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Mina ist stark genug, um zu überleben. Davon bin ich fest überzeugt."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Mina est suffisamment forte pour avoir survécu. J'en suis convaincu."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
