L49_1 = "SPRING_ACT1_EPILOUGE@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 1300010
L48_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_LAUGH"
L48_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L48_1.m_Pos = "R"
L49_1 = "물론. 학생회장은 반드시 살아 있을 거다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "もちろんだ。生徒会長は絶対に生きている。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Definitely. The Student President is definitely alive."
L48_1.m_Talk_ENG = L49_1
L49_1 = "那當然，學生會長一定還活著。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แน่นอน ประธานนักเรียนจะต้องมีชีวิตอยู่อย่างแน่นอน"
L48_1.m_Talk_THA = L49_1
L49_1 = "Chắc chắn. Chủ Tịch Hội Học Sinh chắc chắn còn sống."
L48_1.m_Talk_VTN = L49_1
L49_1 = "那当然，学生会长一定还活着。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Definitiv. Die Schülerpräsidentin ist bestimmt noch am Leben."
L48_1.m_Talk_DEU = L49_1
L49_1 = "C'est certain. La présidente du Conseil est en vie."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "SPRING_ACT1_EPILOUGE@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 1300010
L49_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L49_1.m_bWaitClick = true
