L50_1 = "YOO_JIN_ALT_SPRING_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "L"
L50_1 = 40
L49_1.m_Crash = L50_1
L50_1 = "그럼 이럴 때가 아니잖아! 당장 출발해야 하는 거 아냐?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "だったらこうしてる場合じゃないだろう！\n今すぐ出発しないとダメじゃないか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Then, what are we still doing here? Shouldn't we take off already?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "現在就馬上出發吧！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แล้ว เรามัวทำอะไรกันอยู่ตรงนี้ล่ะ? ไม่รีบออกยานกันเหรอคะ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Vậy thì, chúng ta còn làm gì ở đây thế? Không phải chúng ta nên cất cánh sao?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "那现在最好马上就出发吧！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Was machen wir dann noch hier? Sollten wir nicht längst loslegen?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Alors qu'est-ce qu'on fait encore là ? On ne devrait pas y aller ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
