L2_1 = "SPRING_ACT1_EPILOUGE@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 1300010
L1_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "ADMIN_SCHOOL_NULL_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "다들 학생회장을 생각해 줘서 고맙군요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "みんな生徒会長のことを思ってくれるなんて、ありがたいですね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Everyone, I'm glad that you all care so much about the Student President."
L1_1.m_Talk_ENG = L2_1
L2_1 = "謝謝大家這麼惦念學生會長。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ทุกคน ฉันดีใจที่พวกเธอเป็นห่วงประธานนักเรียนกันมากขนาดนี้"
L1_1.m_Talk_THA = L2_1
L2_1 = "Các em, thầy rất vui vì tất cả các em đều quan tâm đến Chủ Tịch Hội Học Sinh nhiều như vậy."
L1_1.m_Talk_VTN = L2_1
L2_1 = "谢谢大家还惦念着学生会长。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Es freut mich, dass euch die Schülerpräsidentin so sehr am Herzen liegt."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je suis heureux de voir à quel point vous tenez à la présidente du Conseil."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "SPRING_ACT1_EPILOUGE@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 1300010
L2_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "ADMIN_SCHOOL_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "하지만 너무 서두르면 일을 그르치게 됩니다. 지금은 차원계면이 불안정해서 다이브하기엔 몹시 위험한 상태니까요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "だからといって、急ぎ過ぎてはいけません。\n今は次元界面が不安定なので、ダイブするには大変危険な状態なのです。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "But haste makes waste. Right now, the dimension surface is too unstable to be dived into."
L2_1.m_Talk_ENG = L3_1
L3_1 = "但我們如果操之過急，反而會把事情搞砸。因為現在次元邊界還不穩定，躍入是非常危險的。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "แต่รีบร้อนไปก็จะทำให้เสียงาน ในตอนนี้ พื้นผิวมิติยังไม่เสถียรพอที่จะไดฟ์"
L2_1.m_Talk_THA = L3_1
L3_1 = "Nhưng dục tốc bất đạt. Hiện tại, Biên Giới Thứ Nguyên quá không ổn định để có thể lặn xuống."
L2_1.m_Talk_VTN = L3_1
L3_1 = "但是操之过急，反而会把事情搞砸。因为现在的次元边界还不太稳定，所以跃入是非常危险的。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Aber gut Ding will Weile haben – momentan ist die Oberfläche der Dimension zu instabil, um sie zu betauchen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Mais nous ne devons pas nous précipiter. Actuellement, la surface dimensionnelle est trop instable pour que nous y plongions."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "SPRING_ACT1_EPILOUGE@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 1300010
L3_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "ADMIN_SCHOOL_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "너무 조급해하지 말고 여유를 가집시다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "焦らずに余裕を持ちましょう。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Let's try to not be too impatient."
L3_1.m_Talk_ENG = L4_1
L4_1 = "所以大家不要急，先放鬆一下。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อย่าใจร้อนไปจะดีกว่า"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hãy cố gắng đừng quá mất kiên nhẫn."
L3_1.m_Talk_VTN = L4_1
L4_1 = "别急，大家放松一下。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wir müssen noch ein wenig Geduld bewahren."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ne soyons pas hâtifs."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "SPRING_ACT1_EPILOUGE@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 1300010
L4_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "ADMIN_SCHOOL_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "게다가 이번에 학교를 떠나면, 이렇게 푸른 하늘 아래 꽃이 피는 모습도 당분간 보기 어려울 거에요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "それに校舎を離れたら、当分は青空の下に花が咲いている姿も見られなくなるでしょう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Besides, once we leave the school, we won't be able to see this blue sky or flowers for a long time."
L4_1.m_Talk_ENG = L5_1
L5_1 = "況且這次我們離開學校後，會有一段時間很難再看到藍天下花開的樣子。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "นอกจากนี้ เมื่อเราไปจากโรงเรียนแห่งนี้ เราก็จะไม่ได้เห็นท้องฟ้าสีครามและดอกไม้แบบนี้ไปอีกนาน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Hơn nữa, một khi rời khỏi trường, chúng ta sẽ không thể nhìn thấy bầu trời xanh và những bông hoa này trong một thời gian dài."
L4_1.m_Talk_VTN = L5_1
L5_1 = "而且这次我们离开学校后，暂时还很难再看到蓝天下花开的样子了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Und übrigens: Sobald wir die Schule verlassen, werden wir diesen blauen Himmel und die Blumen für lange Zeit nicht mehr sehen können."
L4_1.m_Talk_DEU = L5_1
L5_1 = "De plus, une fois que nous aurons quitté l'école, nous n'aurons plus souvent l'occasion de revoir le ciel bleu et les fleurs de cerisiers."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "SPRING_ACT1_EPILOUGE@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 1300010
L5_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "ADMIN_SCHOOL_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "그러니 오늘만큼은 수업을 쉬기로 하죠."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "だから、今日くらいは授業をお休みしましょうか。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "So, why don't we skip class today and enjoy them?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "那今天就放假一天吧。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เพราะฉะนั้น เรามาหยุดเรียนและใช้เวลาชื่นชมสิ่งเหล่านี้กันเถอะ ดีมั้ย?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Vì vậy, sao chúng ta không bỏ qua tiết học ngày hôm nay và tận hưởng khoảnh khắc này nhỉ?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "所以今天决定休息一天。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Also lassen wir heute den Unterricht ausfallen, damit ihr sie genießen könnt."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Alors, pourquoi ne pas oublier les cours du jour pour en profiter ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
