L7_1.m_Crash = 30
L8_1 = "수업을 안 해? 정말?!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "授業をしない？　本当！？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "We can skip class? Really?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "不上課嗎？真的嗎？！！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เราโดดเรียนได้เหรอคะ? จริงเหรอคะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Bọn em có thể nghỉ học ư? Có thật không?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "不上课?真的吗？！！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Der Unterricht fällt aus? Wirklich?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "On a le droit de sécher les cours ? Vraiment ?"
L7_1.m_Talk_FRA = L8_1
