L9_1 = 60
L8_1.m_Crash = L9_1
L9_1 = "좋았어! 그럼 좀 더 달려 보실까? 아이리님 나가신다!!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "よし！　じゃあもっと走ろうかな！　アイリ様が行くよぉ！！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Alright! I'm going to drive my scooter again! Here goes Irie!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "太棒了！那我再去飆一下蓬蓬好了♪艾莉出發囉！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เอาล่ะ! ฉันจะไปขี่สกูตเตอร์ล่ะนะ! ไอรี่มาแล้ว!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Được rồi! Em sẽ lái xe ga thêm một vòng nữa! Irie đến đây!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "太棒了！那么再去飞奔一会好了！本艾力大人先出去了!"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Mega! Dann fahre ich wieder mit dem Roller! Ab gehts, Irie!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Super, je retourne faire du scooter ! Laissez passer Irie !"
L8_1.m_Talk_FRA = L9_1
