L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 1300010
L10_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "ADMIN_SCHOOL_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "아, 잠시만. 그러기 전에......"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あ、待ってください。その前に……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Ah, wait. Before we do..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "啊，等一下。在這之前…"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เอ่อ เดี๋ยวก่อนนะ..."
L10_1.m_Talk_THA = L11_1
L11_1 = "À, đợi đã. Trước khi chúng ta nghỉ học..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "啊,等一下。在此之前..."
L10_1.m_Talk_SCN = L11_1
L11_1 = "Äh, wartet … Einen Moment noch."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Ah, une minute. Avant de partir..."
L10_1.m_Talk_FRA = L11_1
