L13_1 = "SPRING_ACT1_EPILOUGE@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 1300010
L12_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "SEO_YOON_ALT_SPRING_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "네. 오늘 아침부터 학생들과 학교의 모습을 모두 촬영해 뒀어요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "はい。今朝から生徒たちと学校の様子をすべて撮影しておきました。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Yes, I've been filming the students and the school since this morning."
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯，差不多了，我從早上就把同學和校園樣子全部拍下來了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ค่ะ ฉันถ่ายวิดีโอนักเรียนและโรงเรียนมาตั้งแต่เช้าแล้ว"
L12_1.m_Talk_THA = L13_1
L13_1 = "Vâng, em đã quay phim các học sinh và trường học từ sáng nay."
L12_1.m_Talk_VTN = L13_1
L13_1 = "嗯，差不多了，我从早上开始就把同学们和校园的样子全都拍下来了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ja … Ich habe die Schüler und die Schule seit heute Morgen gefilmt."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ah, oui, je filme les élèves et l'école depuis ce matin."
L12_1.m_Talk_FRA = L13_1
