L15_1 = "SPRING_ACT1_EPILOUGE@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 1300010
L14_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "ADMIN_SCHOOL_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "좋아요. 그럼 이제 마무리만 남았군요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "いいですね。残りはこれだけですか。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Good. Now, we just need a proper ending."
L14_1.m_Talk_ENG = L15_1
L15_1 = "非常好，那現在只剩最後的收尾了。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ดีมาก เอาล่ะ เราต้องมีฉากจบที่เหมาะสมนะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tốt lắm. Bây giờ, chúng ta chỉ cần một cái kết thích hợp."
L14_1.m_Talk_VTN = L15_1
L15_1 = "好的，那现在只剩下收尾工作了。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Gut. Jetzt brauchen wir nur noch ein ordentliches Ende."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Bien. Il ne nous manque plus qu'une fin digne de ce nom."
L14_1.m_Talk_FRA = L15_1
