L16_1 = "SPRING_ACT1_EPILOUGE@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 1300010
L15_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "ADMIN_SCHOOL_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "각자 자유시간을 갖기 전에, 다들 한자리에 모여 보도록 할까요?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "各自、自由行動をする前に一か所に集まってください！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Before everyone goes off to enjoy their free time, shall we gather around for one last time?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "在自由活動之前，大家先這邊集合一下吧？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ก่อนที่ทุกคนจะออกไปสนุกกับเวลาว่าง เรามาถ่ายรูปร่วมกันเป็นครั้งสุดท้ายดีมั้ย?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Trước khi mọi người ra ngoài để tận hưởng thời gian rảnh rỗi, chúng ta nên tập hợp lại lần cuối chứ nhỉ?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "在各自拥有自由活动的时间前,大家聚一聚怎么样?"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Bevor sich alle in ihre Freizeit begeben, sollten wir uns noch ein letztes Mal versammeln."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Avant que vous partiez tous profiter de votre temps libre, voulez-vous bien vous regrouper une dernière fois ?"
L15_1.m_Talk_FRA = L16_1
