L19_1 = "SPRING_ACT1_EPILOUGE@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 1300010
L18_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L18_1.m_Pos = "L"
L19_1 = "참전 전의 사진 촬영이군요. 알겠습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "参戦前の写真撮影ですね。わかりました。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "You want to take a photo with everyone before the war. Understood."
L18_1.m_Talk_ENG = L19_1
L19_1 = "上戰場前的大合照嗎，好的。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อยากจะถ่ายรูปกับทุกคนก่อนทำสงครามสินะ เข้าใจแล้วครับ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Thầy muốn chụp ảnh chung với mọi người trước chiến tranh. Đã hiểu."
L18_1.m_Talk_VTN = L19_1
L19_1 = "上战场前的照片啊。好的。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Sie wollen ein Foto mit allen vor dem Krieg machen? Verstehe."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Vous voulez qu'on prenne une photo de groupe avant la guerre. Je comprends."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "SPRING_ACT1_EPILOUGE@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 1300010
L19_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SURPRISE"
L19_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L19_1.m_Pos = "R"
L20_1 = "졸업사진인가...... 이렇게 갑작스레 찍게 될 줄은 몰랐는데."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "卒業写真か……\nこんな風にいきなり撮ることになるとは思わなかったな。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "A graduation photo... I didn't know it'd be so sudden."
L19_1.m_Talk_ENG = L20_1
L20_1 = "算是畢業照嗎… 沒想到會拍得這麼突然。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "รูปถ่ายเนื่องในโอกาสจบการศึกษา... ไม่นึกว่าจะกะทันหันแบบนี้นะเนี่ย"
L19_1.m_Talk_THA = L20_1
L20_1 = "Một bức ảnh tốt nghiệp... Mình không ngờ là sẽ đột ngột như vậy."
L19_1.m_Talk_VTN = L20_1
L20_1 = "而且还是毕业照啊...没想到拍得这么突然。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ein Schulabschlussfoto … Ich hätte nicht gedacht, dass es so plötzlich kommen würde."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Une photo de remise des diplômes... C'est arrivé si vite."
L19_1.m_Talk_FRA = L20_1
