L22_1 = "SPRING_ACT1_EPILOUGE@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 1300010
L21_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "ADMIN_SCHOOL_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "이번에 찍은 것들은 모두 타임캡슐에 봉인해 두겠습니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "今日撮ったものはすべてタイムカプセルに封印しておきます。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I'll put all the videos and photos in a time capsule."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這次拍的東西，我都把它封存在時光膠囊裡。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฉันจะนำวิดีโอและรูปถ่ายพวกนี้ใส่ในแคปซูลกาลเวลา"
L21_1.m_Talk_THA = L22_1
L22_1 = "Thầy sẽ đặt tất cả video và ảnh vào một Hộp Thời Gian."
L21_1.m_Talk_VTN = L22_1
L22_1 = "这次拍的东西，我都会封存在时光宝盒里的。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich werde alle Videos und Fotos in eine Zeitkapsel packen."
L21_1.m_Talk_DEU = L22_1
L22_1 = "J'ai placé les vidéos et les photos dans une capsule temporelle."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "SPRING_ACT1_EPILOUGE@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 1300010
L22_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "ADMIN_SCHOOL_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "학생회장을 구출하고 나면, 함께 열어 보기로 하죠."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "生徒会長の救出が終わったら、みんなで開けることにしましょう。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "We can open it together after we save the Student President."
L22_1.m_Talk_ENG = L23_1
L23_1 = "等救出學生會長後，我們一起打開看看吧。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ถ้าเราช่วยประธานนักเรียนสำเร็จ เราก็จะมาเปิดแคปซูลกัน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Chúng ta có thể mở nó cùng nhau sau khi cứu được Chủ Tịch Hội Học Sinh."
L22_1.m_Talk_VTN = L23_1
L23_1 = "等到救出学生会长后，我们一起打开看看。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wir können sie gemeinsam öffnen, nachdem wir die Schülerpräsidentin gerettet haben."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Nous les redécouvrirons ensemble une fois la présidente du Conseil sauvée."
L22_1.m_Talk_FRA = L23_1
