L25_1 = "SPRING_ACT1_EPILOUGE@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 1300010
L24_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L24_1.m_bWaitClick = true
