L26_1 = "SPRING_ACT1_EPILOUGE@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 1300010
L25_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "SEO_YOON_ALT_SPRING_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "대신 우리끼리만 찍으면 미안하니까, 학생회장에게 보내는 인사 영상도 함께 찍어 보죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "でも、私たちだけだと申し訳ないので、\n生徒会長に送る挨拶の動画も一緒に撮りましょう。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Since the Student President can't take a photo with us today, how about we record a video message for her?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "但就只有我們拍的話太對不起學生會長了，不如我們也拍個問候學生會長的影片吧。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เนื่องจากประธานนักเรียนมาถ่ายรูปกับพวกเราไม่ได้ในวันนี้ เรามาอัดข้อความวิดีโอให้เธอกันดีมั้ยคะ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Vì hôm nay Chủ Tịch Hội Học Sinh không thể chụp ảnh với chúng ta, vậy chúng ta sẽ nhắn gửi cho cậu ấy qua video nhé?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "但是只有我们自娱自乐可不好，不如我们也一起拍一段给学生会长的问候视频吧！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Da die Schülerpräsidentin heute kein Foto mit uns machen kann – wie wäre es, wenn wir eine Videobotschaft für sie aufnehmen?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Puisque la présidente du Conseil n'est pas là pour prendre une photo avec nous, et si on lui enregistrait un message vidéo ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "SPRING_ACT1_EPILOUGE@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 1300010
L26_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_PRIDE"
L27_1 = "YOO_JIN_ALT_SPRING_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L26_1.m_Crash = 30
L27_1 = "헤헤, 그거 보여주면 감동해서 울어 버리는 거 아냐?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ヘヘ、それ見せたら感動して泣いちゃうんじゃないか？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Heh heh. She might cry if she sees it."
L26_1.m_Talk_ENG = L27_1
L27_1 = "嘿嘿，要是她看了那段影片肯定會感動到哭吧。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แหะแหะ ถ้าเธอเห็นเข้าคงจะร้องไห้ขี้มูกโป่งแน่ๆ"
L26_1.m_Talk_THA = L27_1
L27_1 = "He he. Cậu ấy có thể khóc nếu nhìn thấy tin nhắn đấy."
L26_1.m_Talk_VTN = L27_1
L27_1 = "嘿嘿，会长看到了视频，会不会感动得哭出来呢？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Hihi … Vielleicht weint sie dann, wenn sie es sieht …"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Hé hé hé, si elle voit ça, elle va pleurer."
L26_1.m_Talk_FRA = L27_1
