L30_1 = "SPRING_ACT1_EPILOUGE@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 1300010
L29_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "ADMIN_SCHOOL_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "그럼 다들 사진을 찍어 보죠. 평소처럼 자연스러운 모습이면 됩니다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "では撮りましょうか。普段どおりの自然な姿で構いませんよ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Now, everyone. Let's take a photo. I want everyone to look natural."
L29_1.m_Talk_ENG = L30_1
L30_1 = "在那之後大家就來拍照吧，就像平時那樣，自然一點就行了。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เอาล่ะทุกคน มาถ่ายรูปกันเถอะ ฉันอยากให้ทุกคนทำตัวเป็นธรรมชาตินะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Bây giờ, tất cả các em. Hãy chụp một bức ảnh. Thầy muốn mọi người trông thật tự nhiên."
L29_1.m_Talk_VTN = L30_1
L30_1 = "那大家就照张相吧，平时那样，自然一点就可以了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Also, Leute. Wir machen ein Foto. Ich möchte, dass alle natürlich aussehen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Allez, venez prendre cette photo. J'aimerais que tout le monde reste naturel."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SPRING_ACT1_EPILOUGE@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 1300010
L30_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L30_1.m_Pos = "C"
L31_1 = "평소의 자연스러운 모습이라...... 그렇다면 첫 테마는 등굣길이 좋겠군요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "普段どおりの自然な姿か……それなら、最初のテーマは登校がいいですね。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You want everyone to look natural. Then, we suggest we take our first photo on the road to school."
L30_1.m_Talk_ENG = L31_1
L31_1 = "平時的樣子啊...那麼第一個主題就是上學囉。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ถ้าอยากให้เป็นธรรมชาติ ผมแนะนำว่าเราควรจะถ่ายรูปแรกตรงถนนทางเข้าโรงเรียนครับ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Thầy muốn mọi người trông thật tự nhiên. Vậy thì bọn em đề nghị hãy chụp bức ảnh đầu tiên trên con đường đến trường."
L30_1.m_Talk_VTN = L31_1
L31_1 = "平时的样子啊...那么我建议第一个主题就用“上学路上”。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Sie wollen, dass alle natürlich aussehen? Dann schlage ich vor, das wir das erste Foto auf dem Schulweg machen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Si vous voulez qu'on ait l'air naturel, je suggère qu'on prenne notre première photo sur la route qui mène à l'école."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "SPRING_ACT1_EPILOUGE@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 1300010
L31_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_LAUGH"
L31_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L31_1.m_Pos = "C"
L31_1.m_Crash = 30
L32_1 = "오~ 아이리 님도 대찬성! 마지막 등교, 신나게 뛰어올 테야! "
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "おお～アイリ様も大賛成！　最後の登校、楽しく走っちゃうぞ！ "
L31_1.m_Talk_JPN = L32_1
L32_1 = "Oooh, Irie seconds that! Irie wants to come running to school for one last time! "
L31_1.m_Talk_ENG = L32_1
L32_1 = "噢~ 艾莉超級贊成！最後一天上學，我興奮到跳起來♪"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โอ้วว ไอรี่เห็นด้วย! ไอรี่อยากมีภาพตัวเองวิ่งมาโรงเรียนเป็นครั้งสุดท้ายสักใบ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Oooh, Irie đứng thứ hai nhé! Irie muốn chạy đến trường lần cuối!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "啊~ 哎哟，本艾力大人也举双手赞成！最后一天上学，我会兴奋地骑车飞奔过来的!"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Oh, das findet Irie mega! Irie will ein letztes Mal zur Schule laufen! "
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oooh ! Irie est totalement d'accord ! Elle veut courir sur le chemin de l'école une dernière fois ! "
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "SPRING_ACT1_EPILOUGE@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 1300010
L32_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L32_1.m_Pos = "C"
L33_1 = "등굣길도 나쁘지 않군. 교실 안에선 벚꽃이 잘 안 보이니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "通学路も悪くないな。教室の中だと桜がよく見えないから。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "That's not a bad idea. We can't see the cherry blossoms from the inside of our classrooms."
L32_1.m_Talk_ENG = L33_1
L33_1 = "上學的路也很漂亮啊，雖然在教室裡看太不清楚外面的櫻花。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ไม่เลวนะ ถ้าเป็นในห้องเรียนล่ะก็ เราคงไม่ได้เห็นต้นซากุระแน่"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đó không phải là một ý tồi đâu. Chúng ta không thể nhìn thấy hoa anh đào từ bên trong lớp học của mình."
L32_1.m_Talk_VTN = L33_1
L33_1 = "嗯，这个主意不错，在教室里可看太不清外面的樱花。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das ist keine schlechte Idee, denn von den Klassenzimmern aus können wir die Kirschblüten nicht sehen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ce n'est pas bête. On ne peut pas voir les cerisiers en fleurs depuis l'intérieur de l'école."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SPRING_ACT1_EPILOUGE@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 1300010
L33_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SURPRISE"
L33_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L33_1.m_Pos = "C"
L34_1 = "음? 그런데 교장 선생님께선 오시지 않는 겁니까?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "あれ？　校長先生は入らないんですか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Mm? Mr. Principal, aren't you coming with us?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "咦？話說回來，校長您不過來嗎?"
L33_1.m_Talk_TWN = L34_1
L34_1 = "หืม? คุณครูใหญ่ คุณไม่มาถ่ายด้วยเหรอครับ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Mm? Thầy Hiệu Trưởng, thầy không đi với bọn em sao?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "嗯？可是校长不来吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hm? Herr Rektor, kommen Sie nicht mit?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hmm ? Monsieur le principal, vous ne venez pas avec nous ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
