L36_1 = "ADMIN_SCHOOL_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "네, 좋은 장면을 놓치지 않으려면 누군가는 사진을 찍어 줘야 하는 법이니까요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ええ。いい瞬間を逃さないためには、誰かがシャッターを押さないといけませんからね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I am. Someone has to take a photo of you and make sure you all look nice."
L35_1.m_Talk_ENG = L36_1
L36_1 = "是啊，如果要拍出好的畫面，一定要有誰去按快門才行。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เดี๋ยวฉันไปอยู่แล้ว แต่ก่อนอื่น ต้องมีใครสักคนเป็นคนถ่ายนะ พวกเธอทุกคนจะได้ดูดีไงล่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Có chứ. Phải có người chụp ảnh các em và đảm bảo tất cả các em thật đẹp còn gì."
L35_1.m_Talk_VTN = L36_1
L36_1 = "没错，如果不想漏拍好的画面，一定要有谁去拍快门才行。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Doch – es muss euch ja jemand fotografieren und sicherstellen, dass ihr alle gut ausseht."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Si, mais quelqu'un doit se charger de prendre la photo et s'assurer que vous êtes tous beaux."
L35_1.m_Talk_FRA = L36_1
