L42_1 = "L_M_I"
L41_1.m_Pos = L42_1
L42_1 = "아이리 님이 준비해 뒀던 비장의 트랩이란 말씀♪"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "アイリ様が用意した、とっておきのトラップだよ♪"
L41_1.m_Talk_JPN = L42_1
L42_1 = "From Irie's special traps! ♪"
L41_1.m_Talk_ENG = L42_1
L42_1 = "是艾莉準備的盛大陷阱啦♪"
L41_1.m_Talk_TWN = L42_1
L42_1 = "จากกับดักพิเศษของไอรี่ไงล่ะ! ♪"
L41_1.m_Talk_THA = L42_1
L42_1 = "Từ những cái bẫy đặc biệt của Irie đấy! ♪"
L41_1.m_Talk_VTN = L42_1
