L42_1.m_Face = "UNIT_PRIDE"
L42_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L43_1 = "R_M_I"
L42_1.m_Pos = L43_1
L43_1 = "이 전학생이 소매 걷고 도와 줬지. 훗훗훗."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "この転校生が一肌脱いだのさ。ふっふっふっ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "And the Transfer Student helped her set them up. Hah hah hah."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我這轉學生也幫了點忙呢，呵呵。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "และนักเรียนใหม่ก็ช่วยเธอวางกับดักด้วย ฮ่าฮ่าฮ่า"
L42_1.m_Talk_THA = L43_1
L43_1 = "Và Học Sinh Chuyển Trường đã giúp thiết lập chúng. Há há há."
L42_1.m_Talk_VTN = L43_1
L43_1 = "以及转校生的大力支持！哈哈哈！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Und die Austauschschülerin hat beim Aufbau geholfen, haha!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "N'oubliez pas l'élève transférée qui a aidé à les installer, ha ha ha."
L42_1.m_Talk_FRA = L43_1
