L44_1 = "SPRING_ACT1_EPILOUGE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 1300010
L43_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L43_1.m_Pos = "R"
L43_1.m_Crash = 20
L44_1 = "마지막으로 볼지도 모르는 꽃잎, 다 함께 기억에 생생하게 새겨 놓자고 하는 그 아름다운 우정 이벤트......!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "最後になるかもしれない花びらを\nみんなの記憶に鮮やかに刻む美しい友情のイベント……！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "A beautiful event for our friends, to make the sight of possibly our last flowers most memorable!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "在最後，你也許會想要看到櫻花飛舞在這場美麗的友情活動上……!"
L43_1.m_Talk_TWN = L44_1
L44_1 = "อีเวนต์อันงดงามแด่ผองเพื่อน เพื่อให้ภาพของดอกไม้ที่เราอาจได้เห็นเป็นครั้งสุดท้าย คือความทรงจำอันแสนงดงาม!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Một sự kiện tuyệt vời cho những người bạn của chúng ta, khiến việc ngắm nhìn những bông hoa cuối cùng trở thành những ký ức đáng nhớ nhất!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "最后也不知道能不能看到花瓣啦，所以难得，让我们一起铭记这个美丽的友情活动......!"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ein schönes Event für unsere Freunde, um den Anblick unserer vorerst letzten Blüten unvergesslich zu machen!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "C'est une merveilleuse surprise pour nos amis, et pour rendre la vue de nos dernières fleurs de cerisier plus mémorable !"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
