L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "名付けてフラワーエクスプロージョン！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "It's called the Flower Explosion!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "命名為——百花爆炸！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ขอให้ชื่อว่า ระเบิดบุปผา!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nó được gọi là Vụ Nổ Hoa!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "活动的名字就是——在花海中游泳！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Das ist die Blütenexplosion!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "On a appelé ça l'explosion florale !"
