L45_1.m_Crash = 30
L46_1 = "전학생은 뜨거운 눈물을 흘리면서 계획에 동참한 것이었다......!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "転校生は熱い涙を流しながら計画に参加したのである……！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The Transfer Student joined Irie's plan, shedding hot tears of strong emotions!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "我這轉學生是含著熱淚參加本次計畫呢……!"
L45_1.m_Talk_TWN = L46_1
L46_1 = "นักเรียนใหม่ร่วมมือทำตามแผนของไอรี่ พร้อมหลั่งน้ำตาอันร้อนแรงจากอารมณ์อันสะท้านสะเทือน!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Học Sinh Chuyển Trường đã tham gia vào kế hoạch của Irie, rơi nước mắt vì cảm xúc mạnh mẽ!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "本转校生可是含着感动的热泪参与了艾力的计划呢。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Die Austauschschülerin hat sich Iries Plan angeschlossen und heiße Tränen der Rührung vergossen!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "L'élève transférée s'est jointe au plan d'Irie, des larmes d'émotion se déversant sur ses joues !"
L45_1.m_Talk_FRA = L46_1
