L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 1300010
L47_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_LAUGH"
L48_1 = "YOO_JIN_ALT_SPRING_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "이 정도 양의 벚꽃을 모으려면 꽤 고생했겠는데? 전부 너희가 모은 거야?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "これだけの桜を集めるなんて、かなり苦労しただろ？　全部二人で集めたのか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It must have taken a long time to collect so many cherry blossoms. Did you collect them all by yourselves?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "要收集這麼多的櫻花應該很辛苦吧? 這都是妳收集的嗎?"
L47_1.m_Talk_TWN = L48_1
L48_1 = "กว่าจะหากลีบดอกซากุระมาได้เยอะขนาดนี้คงต้องใช้เวลานานน่าดู เธอทำเองหมดนี่เลยเหรอ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chắc phải tốn thời gian lắm mới thu thập được nhiều hoa anh đào như vậy. Cậu đã làm tất cả chuyện này một mình ư?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "收集这么多的樱花应该很辛苦吧? 都是你们拼凑来的吗?"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Es muss lange gedauert haben, so viele Kirschblüten zu sammeln … Habt ihr sie alle selbst gesammelt?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ça a dû prendre un temps fou de ramasser tous ces pétales. Vous avez fait ça toutes seules ?"
L47_1.m_Talk_FRA = L48_1
