L49_1 = "우리 집 전속 집사들이 밤새."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "我が家の専属執事たちが夜通しで。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "My family butlers did all night."
L48_1.m_Talk_ENG = L49_1
L49_1 = "是我家的管家們花了一個晚上做的！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เปล่า ฉันให้พ่อบ้านของตระกูลเป็นคนไปเก็บทั้งคืนเลย"
L48_1.m_Talk_THA = L49_1
L49_1 = "Các quản gia của gia đình tôi đã mất cả đêm để đi lượm hoa đấy."
L48_1.m_Talk_VTN = L49_1
L49_1 = "是我家的管家们通宵达旦搞来的！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Die Butler meiner Familie haben die ganze Nacht durchgearbeitet."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Les majordomes de ma famille s'en sont chargés cette nuit."
L48_1.m_Talk_FRA = L49_1
