L50_1 = "우와...... 마지막에 확 깬다, 야......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "うわぁ……最後の一言で冷めるぜ……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Geez, that totally killed the mood girl."
L49_1.m_Talk_ENG = L50_1
L50_1 = "…覺得好像突然領悟了什麼，哈哈…"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ให้ตายสิ ฟังแบบนี้แล้วหมดมู้ดเลย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ôi, điều đó đã hoàn toàn giết chết tâm trạng thiếu nữ của tôi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "...最后一下子醒悟了,哈哈..."
L49_1.m_Talk_SCN = L50_1
L50_1 = "Oje … die Erkenntnis drückt jetzt wirklich auf die Stimmung …"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Waouh, tu as plombé l'ambiance, Xien."
L49_1.m_Talk_FRA = L50_1
