L2_1 = "SPRING_ACT1_EPILOUGE@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 1300010
L1_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "ADMIN_SCHOOL_NULL_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "하하, 그래도 마지막인 만큼 멋진 사진이 나오겠네요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "はは、でも最後なだけに素敵な写真が撮れそうですね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Hah hah, but this will make our last photo together look amazing."
L1_1.m_Talk_ENG = L2_1
L2_1 = "哈哈，但畢竟這是最後一次了，我們一定能拍出很好的照片。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฮ่าฮ่า แต่นั่นก็ทำให้ภาพถ่ายสุดท้ายของพวกเราสวยมากเลยนะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ha ha, nhưng thứ này sẽ làm cho bức ảnh chụp chung cuối cùng của chúng ta trở nên tuyệt vời."
L1_1.m_Talk_VTN = L2_1
L2_1 = "哈哈，但毕竟是最后一次了嘛，应该会拍出帅气的照片吧。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "So oder so, unser letztes gemeinsames Foto wird fantastisch aussehen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Ha ha ha, mais grâce à vous, notre dernière photo de groupe s'annonce incroyable."
L1_1.m_Talk_FRA = L2_1
