L4_1 = "SPRING_ACT1_EPILOUGE@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 1300010
L3_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SURPRISE"
L4_1 = "YOO_JIN_ALT_SPRING_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L3_1.m_Crash = 30
L4_1 = "아, 잠깐! 야옹아! 어디 가는 거야!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あっ、待て！　にゃんこちゃん！　どこ行くんだよ！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ah, wait! Kitty cat! Where are you going?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "啊，等一下！小貓貓！你去哪啊！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อ๊ะ รอก่อนสิ เจ้าเหมียว แกจะไปไหนน่ะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "À, đợi đã! Mèo con! Mày đi đâu vậy?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "啊, 等一下! 小猫猫啊！你去哪儿啊!"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ah, Moment! Katerchen! Wo willst du hin?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ah, attends ! Où tu vas comme ça, petit chat ?"
L3_1.m_Talk_FRA = L4_1
