L6_1 = "SEO_YOON_ALT_SPRING_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "L"
L6_1 = "꽃잎이 날리는 게 신기했나 보네. 금방 돌아올 테니까 서운해하지 마."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "花びらが舞うのが不思議だったみたいね。\nすぐに戻ってくるから寂しがらないで。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "He went after the fluttering petals. Don't worry. He'll be back."
L5_1.m_Talk_ENG = L6_1
L6_1 = "看到花瓣在空中飛舞有一種神奇的感覺呢。我們很快就會回來的，不用這麼難過啦~"
L5_1.m_Talk_TWN = L6_1
L6_1 = "คงจะไล่ตามกลีบดอกไม้พวกนั้นไปน่ะ ไม่ต้องห่วงหรอก เดี๋ยวเขาก็กลับมา"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nó đuổi theo những cánh hoa bay đấy. Đừng lo. Nó sẽ quay trở lại thôi."
L5_1.m_Talk_VTN = L6_1
L6_1 = "“花瓣飘起来，看着很神奇喵。我马上就回来，别舍不得我哦”，小猫猫这么说。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Er rennt den flatternden Blütenblättern hinterher. Keine Sorge, er kommt zurück."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Il est parti courir après les pétales. Ne t'inquiète pas, il va revenir !"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "SPRING_ACT1_EPILOUGE@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 1300010
L6_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_HATE"
L7_1 = "YOO_JIN_ALT_SPRING_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "R"
L6_1.m_Crash = 30
L7_1 = "서, 서운하긴 누가 서운해한다고 그래?!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "さ、寂しいなんて思ってないからな！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Wh-who says I'm worried?!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "妳說誰難過？我才不難過！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "คะ-ใครบอกว่าเป็นห่วงกัน?!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ai nói là tôi lo lắng chứ?!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "谁、谁舍不得你了！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wer sagt, dass ich mir Sorgen mache?!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "J-Je suis pas inquiète !"
L6_1.m_Talk_FRA = L7_1
