L8_1 = "SPRING_ACT1_EPILOUGE@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 1300010
L7_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_LAUGH"
L7_1.m_CharStrID = "IRIE_CIVIL_SPRING_NULL"
L8_1 = "L_M_I"
L7_1.m_Pos = L8_1
L8_1 = "이 사진으로 아이리 님의 귀여움을 남겨 둔단 말이지? 리미트 없이 어필할래!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "この写真でアイリ様の可愛さを残すってことね？　リミットなしでアピールするわ！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You want to preserve Irie's cuteness in photos, huh? Knock yourself out!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "這張照片有把艾莉的可愛保存下來嗎？我好想要盡情發揮喔！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "อยากจะบันทึกความสวยของไอรี่ในรูปถ่ายใช่มั้ยล่ะ หืม? ได้เลย!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cậu muốn lưu giữ vẻ dễ thương của Irie trong các bức ảnh, phải không? Cứ tự nhiên!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "这张照片中，有好好把本艾力大人的可爱保留下来吗？biu~正中红心！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Iries Anmut soll auf Fotos festgehalten werden, was? Nur zu!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oh, tu veux tout faire pour qu'Irie soit mignonne sur la photo, c'est ça ? Vas-y !"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SPRING_ACT1_EPILOUGE@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 1300010
L8_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_HATE"
L9_1 = "YOO_JIN_ALT_SPRING_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "R"
L8_1.m_Crash = 30
L9_1 = "앗, 아이리! 너 혼자 너무 들이대잖아!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "あっ、アイリ！　一人だけ顔を近づけすぎだ！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Ah, Irie! You're taking up the whole frame!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "啊！艾莉！妳太愛出風頭了!"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อ๋า ไอรี่! หน้าเธอบังทุกคนหมดแล้วน่ะ!"
L8_1.m_Talk_THA = L9_1
L9_1 = "A, Irie! Cậu đang chiếm hết khung hình mất rồi!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "哎！艾力！不许抢镜！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ah, Irie! Du nimmst das ganze Bild ein!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Hé, Irie ! Tu prends toute la place !"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SPRING_ACT1_EPILOUGE@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 1300010
L9_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ESTAROSSA_ZODIAC_SPRING_NULL"
L9_1.m_Pos = "L"
L10_1 = "유진! 방정맞게 굴지 말고 촬영 때만큼은 얌전히 있도록."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "シロコ！　騒いでないで、撮影の時くらいは大人しくしてろ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Eujin! Stop making a fuss, at least during the photo shoot."
L9_1.m_Talk_ENG = L10_1
L10_1 = "劉珍！別那麼冒失，請像妳射擊的時候一樣安靜。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ยูจิน! เลิกก่อเรื่องได้แล้ว อย่างน้อยก็อยู่นิ่งๆ ตอนถ่ายรูปได้มั้ย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Eujin! Đừng ầm ĩ nữa, ít nhất là trong buổi chụp ảnh này."
L9_1.m_Talk_VTN = L10_1
L10_1 = "刘珍！你也别太冒失了，保持好了动作就不要再动了！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Eujin! Hör auf, rumzustänkern – zumindest während des Fotoshootings."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Eujin ! Arrête de t'agiter, ne serait-ce que le temps de prendre la photo."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
