L11_1 = "윽, 왜 또 나한테만......"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "うっ、なんでまた俺だけ……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Sheesh, I didn't do anything wrong."
L10_1.m_Talk_ENG = L11_1
L11_1 = "唔，為什麼又是我..."
L10_1.m_Talk_TWN = L11_1
L11_1 = "นี่ ฉันยังไม่ได้ทำอะไรผิดเลยนะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Xì, tôi không làm gì sai cả."
L10_1.m_Talk_VTN = L11_1
L11_1 = "额，为什么又只对我这样啊..."
L10_1.m_Talk_SCN = L11_1
L11_1 = "Mann, ich habe doch gar nichts gemacht …"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Pfff, j'ai rien fait, moi."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SPRING_ACT1_EPILOUGE@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 1300010
L11_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "KYLE_DELTA_SPRING_NULL"
L11_1.m_Pos = "L"
L12_1 = "시엔 양, 혼자 바람 맞으면서 독백 그만 읊으시고 이쪽으로 오십시오."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "シエンさん、風に吹かれながら独白するのはやめて、こちらに来てください。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Xien, please stop mumbling to yourself in the wind and come this way."
L11_1.m_Talk_ENG = L12_1
L12_1 = "西恩小姐，請不要一個人迎著風自言自語。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ซีเอิน เลิกพูดบทหนังกับตัวเองกลางสายลมแล้วกลับมาถ่ายรูปได้แล้ว"
L11_1.m_Talk_THA = L12_1
L12_1 = "Xien, ngừng lẩm bẩm một mình trong gió và đến đây nào."
L11_1.m_Talk_VTN = L12_1
L12_1 = "西恩小姐，请不要一个人迎着风吟诵独白了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Xien, bitte hör auf, vor dich hin zu murmeln, und komm her."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Xien, arrêtez de marmonner et venez par ici."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SPRING_ACT1_EPILOUGE@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 1300010
L12_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_PRIDE"
L12_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L12_1.m_Pos = "R"
L13_1 = "후훗, 그렇게까지 내가 필요하다면 어쩔 수 없군."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ふふっ、そんなに私が必要なら仕方ない。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Hah hah. Okay, if you so desperately want me."
L12_1.m_Talk_ENG = L13_1
L13_1 = "哼哼，如果妳這麼需要我的話，真拿妳沒辦法。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฮ่าฮ่า ได้สิ ถ้าต้องการฉันขนาดนั้น"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ha ha. Được rồi, nếu cậu muốn tôi đến thế."
L12_1.m_Talk_VTN = L13_1
L13_1 = "哼哼，如果你这么需要我陪的话，我真拿你没办法。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Haha … Okay, wenn du ohne mich nicht klarkommst …"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ha ha ha, d'accord, si vous me suppliez d'être sur la photo..."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SPRING_ACT1_EPILOUGE@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 1300010
L13_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SERIOUS"
L13_1.m_CharStrID = "XIEN_FREEDOM_SPRING_NULL"
L13_1.m_Pos = "R"
L14_1 = "그런데 말이지 보스, 역시 이렇게 화사한 분위기는 내 하드보일드함이랑 역시 좀 안 맞는 느낌이───"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ところでボス、やはりこんな華やかな雰囲気は私のハードボイルドさと似合わない気が───"
L13_1.m_Talk_JPN = L14_1
L14_1 = "By the way, Boss, maybe this setting is way too feminine for my tough, hard-boiled fictional character image—"
L13_1.m_Talk_ENG = L14_1
L14_1 = "話說老闆，這種活潑的氛圍和我的冷硬派風格有點不搭———"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ว่าแต่ บอสคะ ฉากหลังมันหวานแหววไปรึเปล่า รู้สึกว่ามันไม่เข้ากับบุคลิกในเนื้อเรื่องที่เข้มแข็งและกร้านโลกอย่างฉันเลย—"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhân tiện, Ông Trùm, có lẽ thiết lập bối cảnh này quá nữ tính so với hình tượng nhân vật hư cấu cứng rắn, sắt đá của tôi –"
L13_1.m_Talk_VTN = L14_1
L14_1 = "不过话说老大，这么活泼的氛围，跟我这冷酷的性格还是有点不搭———"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Übrigens finde ich diese Kulisse ein wenig zu feminin für mein hartgesottenes, fiktives Charakter-Image …"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Au fait, boss, cette mise en scène est beaucoup trop féminine pour mon image de personnage dur à cuire et inflexible..."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
