L23_1 = "GAP_BTYPE_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "<color=#ffd34c>관리국 레거시 데이터베이스에 기록. 보안 4등급으로 설정.</color>"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "<color=#ffd34c>管理局レガシーデータベースに記録。セキュリティ4等級に設定。</color>"
L22_1.m_Talk_JPN = L23_1
L23_1 = "<color=#ffd34c>Saved in the Administration's Legacy database. Security level: 4.</color>"
L22_1.m_Talk_ENG = L23_1
L23_1 = "<color=#ffd34c>管理局舊版資料庫記錄，機密等級設定為4。</color>"
L22_1.m_Talk_TWN = L23_1
L23_1 = "<color=#ffd34c>ได้รับการบันทึกในฐานข้อมูลตกทอดขององค์การบริหารโลกแล้ว ระดับความปลอดภัย: 4</color>"
L22_1.m_Talk_THA = L23_1
L23_1 = "<color=#ffd34c>Đã lưu trong Bộ Nhớ Di Sản của Cục Quản Lý. Cấp độ bảo mật: 4.</color>"
L22_1.m_Talk_VTN = L23_1
L23_1 = "<color=#ffd34c>管理局旧版数据库记录，已储存，机密等级：4级。</color>"
L22_1.m_Talk_SCN = L23_1
L23_1 = "<color=#ffd34c>Gespeichert in der Archivdatenbank der Administration. Sicherheitsstufe: 4</color>"
L22_1.m_Talk_DEU = L23_1
L23_1 = "<color=#ffd34c>Données sauvegardées dans la base de données originelle de l'Administration. Niveau de sécurité : 4.</color>"
L22_1.m_Talk_FRA = L23_1
