L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "USER_ADMIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "이제야...... 기억이 조금 떠올랐어."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "やっと……記憶が少しよみがえった。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Finally, I remembered."
L24_1.m_Talk_ENG = L25_1
L25_1 = "終於……浮現了一點記憶。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ในที่สุด ฉันก็จำได้แล้ว"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cuối cùng, mình cũng nhớ ra rồi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "现在才......有点记起来了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Endlich fiel es mir ein."
L24_1.m_Talk_DEU = L25_1
L25_1 = "La mémoire me revient enfin."
L24_1.m_Talk_FRA = L25_1
