L27_1 = "USER_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "결국 타임캡슐은 전하지 못했군."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "結局タイムカプセルは渡せなかった。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "We didn't open the time capsule."
L26_1.m_Talk_ENG = L27_1
L27_1 = "結果還是沒能把這些傳到時光寶盒裡。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เราไม่ได้มีโอกาสเปิดแคปซูลกาลเวลา"
L26_1.m_Talk_THA = L27_1
L27_1 = "Chúng ta đã không mở Hộp Thời Gian đó."
L26_1.m_Talk_VTN = L27_1
L27_1 = "最终，还是没能把这些传到时光宝盒里啊。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wir haben die Zeitkapsel nicht geöffnet."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Nous n'avons jamais rouvert cette capsule temporelle."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "SPRING_ACT1_EPILOUGE@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 1300010
L27_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "USER_ADMIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "그 날, 위험을 무릅쓰고서라도 더 빨리 출발했다면......"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あの日、危険を冒してでも早く出発していれば……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "If we took off earlier that day, regardless of the risks,"
L27_1.m_Talk_ENG = L28_1
L28_1 = "那天，就算要冒著一點危險，但如果能更早出發的話…"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ถ้าวันนั้นเราออกเดินทางเร็วขึ้นอีกหน่อย ไม่ว่ามันจะเสี่ยงแค่ไหน"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nếu chúng ta cất cánh sớm hơn vào ngày hôm đó, bất chấp rủi ro,"
L27_1.m_Talk_VTN = L28_1
L28_1 = "那天，即使冒着一些危险，更早一点出发的话..."
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wenn wir damals früher ausgerückt wären, ungeachtet der Risiken …"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Si nous étions partis plus tôt ce jour-là, en dépit des risques,"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "SPRING_ACT1_EPILOUGE@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 1300010
L28_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "USER_ADMIN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "그랬다면 그녀를 구할 수 있었을까......?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "彼女を救うことができただろうか……？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "would we have saved her?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "那樣就能把她救出來嗎？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เราจะช่วยเธอได้รึเปล่านะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "chúng ta có thể sẽ cứu được cậu ấy chứ?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "那样的话，能救出她吗?"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Hätten wir sie retten können?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "aurions-nous pu la sauver ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SPRING_ACT1_EPILOUGE@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 1300010
L29_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "USER_ADMIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "모든 것을...... 바꿀 수 있었을까......"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "すべてを……変えることができただろうか……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Would we have changed everything?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "一切就…有可能改變嗎..."
L29_1.m_Talk_TWN = L30_1
L30_1 = "ทุกอย่างจะเปลี่ยนแปลงไปรึเปล่า?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Chúng ta có thể thay đổi mọi thứ không?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "一切都...可以改变吗..."
L29_1.m_Talk_SCN = L30_1
L30_1 = "Hätten wir alles geändert?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Aurions-nous pu changer le destin ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SPRING_ACT1_EPILOUGE@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 1300010
L30_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "USER_ADMIN_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "......옛날 일에 집착하는 걸 보니 나도 나이를 먹긴 하나 보군."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "……昔のことに執着するなんて、私も年を取ったようだ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "... I must be getting old, dwelling on old days like this."
L30_1.m_Talk_ENG = L31_1
L31_1 = "…看到自己以前對工作那麼執著的樣子，現在看來我也已經上了年紀了。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "... ฉันคงจะแก่แล้วสินะ ถึงได้จมอยู่กับอดีตแบบนี้"
L30_1.m_Talk_THA = L31_1
L31_1 = "...Chắc là mình già đi rồi, đắm chìm trong những ngày xưa cũ như thế này."
L30_1.m_Talk_VTN = L31_1
L31_1 = "...竟然会执着于往事，现在看来我也上了年纪了啊。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "… Ich werde wohl alt, wenn ich so an lang vergangene Zeiten zurückdenke."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Voilà que je radote... Je dois me faire vieux."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
