L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 1300010
L32_1.m_CutScenStrID = "SPRING_ACT1_EPILOUGE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "USER_ADMIN_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "미안하다, 얘들아. 약속을 지키지 못해서."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "すまない、みんな。約束を守れなくて。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I'm sorry, guys, that I didn't keep the promise."
L32_1.m_Talk_ENG = L33_1
L33_1 = "對不起，孩子們。我沒能遵守約定。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ขอโทษนะทุกคน ที่ฉันทำตามสัญญาที่ให้ไว้ไม่ได้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Xin lỗi các em vì thầy đã không giữ lời hứa."
L32_1.m_Talk_VTN = L33_1
L33_1 = "对不起，孩子们。我没能遵守约定。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Tut mir leid, Leute, dass ich mein Versprechen nicht gehalten habe."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je suis désolé de ne pas avoir tenu ma promesse."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
